script:
(function(){
var root=root_element.querySelector('.dsync');if(!root)return;
var method='cannabis_management.api.daily_sync_dashboards.get_sales_daily_sync_dashboard';
function q(sel){return root.querySelector(sel)}
function qa(sel){return Array.prototype.slice.call(root.querySelectorAll(sel))}
function set(name,val){var els=root.querySelectorAll('[data-kpi="'+name+'"]');els.forEach(function(el){el.innerHTML=val;});}
function money(v){v=parseFloat(v||0);if(Math.abs(v)>=1000000)return '$'+(v/1000000).toFixed(1)+'M';if(Math.abs(v)>=1000)return '$'+(v/1000).toFixed(1)+'K';return '$'+v.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:0})}
function num(v,d){return parseFloat(v||0).toLocaleString(undefined,{maximumFractionDigits:d==null?0:d})}
function pct(v){return num(v,1)+'%'}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function fmtDate(d){if(!d)return'—';var p=String(d).split(' ')[0].split('-');return p.length===3?p[1]+'/'+p[2]+'/'+p[0]:d}

function delta(v,suffix,unit){
  v=parseFloat(v||0);
  var up=v>=0;
  var abs=Math.abs(v);
  var label=(unit==='money'?money(abs):num(abs,1))+(suffix||'');
  var arrow=up?'▲':'▼';
  var cls=up?'dsync-delta-up':'dsync-delta-dn';
  return '<span class="dsync-delta '+cls+'">'+(up?arrow+' +':arrow+' -')+label+' vs prior day</span>';
}

function lineChart(el,rows,key,color){
  if(!el)return;
  rows=rows||[];key=key||'value';
  var vals=rows.map(function(r){return parseFloat(r[key]||0)});
  var max=Math.max.apply(null,vals.concat([0]));
  var min=Math.min.apply(null,vals.concat([0]));
  if(!rows.length||max===0){el.innerHTML='<div class="dsync-chart-empty">No data available for this period</div>';return;}
  var w=620,h=150,p=24,span=Math.max(max-min,1);
  var pts=vals.map(function(v,i){
    var x=p+(i*(w-2*p)/Math.max(vals.length-1,1));
    var y=h-p-((v-min)/span*(h-2*p));
    return[x,y];
  });
  var d=pts.map(function(pt,i){return(i?'L':'M')+pt[0].toFixed(1)+' '+pt[1].toFixed(1)}).join(' ');
  var area=d+' L '+pts[pts.length-1][0]+' '+(h-p)+' L '+pts[0][0]+' '+(h-p)+' Z';
  // X-axis date labels (first, middle, last)
  var labels='';
  if(rows.length>=2){
    var positions=[0,Math.floor(rows.length/2),rows.length-1];
    positions.forEach(function(i){
      var pt=pts[i];
      var lbl=rows[i]?fmtDate(rows[i].date):'—';
      labels+='<text x="'+pt[0].toFixed(1)+'" y="'+(h-4)+'" text-anchor="middle" class="dsync-chart-lbl">'+esc(lbl)+'</text>';
    });
  }
  // Dots on last value
  var lastPt=pts[pts.length-1];
  var lastVal=vals[vals.length-1];
  var tooltip=rows[rows.length-1]?fmtDate(rows[rows.length-1].date)+': '+num(lastVal,0):'—';
  el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">'
    +'<defs><linearGradient id="cg_'+color.replace(/[^a-z0-9]/gi,'')+'" x1="0" y1="0" x2="0" y2="1">'
    +'<stop offset="0%" stop-color="'+color+'" stop-opacity="0.18"/>'
    +'<stop offset="100%" stop-color="'+color+'" stop-opacity="0.02"/>'
    +'</linearGradient></defs>'
    +'<path class="dsync-fill" fill="url(#cg_'+color.replace(/[^a-z0-9]/gi,'')+')" d="'+area+'"></path>'
    +'<path class="dsync-line" style="stroke:'+color+'" d="'+d+'"></path>'
    +'<circle cx="'+lastPt[0].toFixed(1)+'" cy="'+lastPt[1].toFixed(1)+'" r="4" fill="'+color+'" stroke="#fff" stroke-width="2"><title>'+esc(tooltip)+'</title></circle>'
    +'<line class="dsync-axis" x1="'+p+'" y1="'+(h-p+4)+'" x2="'+(w-p)+'" y2="'+(h-p+4)+'"></line>'
    +labels+'</svg>';
}

function table(headers,rows,badges){
  if(!rows||!rows.length)return '<div class="dsync-empty">No data found.</div>';
  return '<table><thead><tr>'+headers.map(function(h){return'<th>'+esc(h.label)+'</th>'}).join('')+'</tr></thead>'
    +'<tbody>'+rows.map(function(r){return'<tr>'+headers.map(function(h){return'<td>'+h.f(r)+'</td>'}).join('')+'</tr>'}).join('')+'</tbody></table>';
}

function renderSales(d){
  var s=d.summary||{},c=d.crm||{};
  set('cod_count','<span class="dsync-big-num">'+num(s.cod_unpaid_count)+'</span>');
  set('cod_count_delta',delta(s.cod_count_delta,''));
  set('cod_amount','<span class="dsync-big-num">'+money(s.cod_unpaid_amount)+'</span>');
  set('cod_amount_delta',delta(s.cod_amount_delta,'','money'));
  var acc=parseFloat(s.prediction_accuracy||0);
  var accCls=acc>=90?'dsync-pct-green':acc>=70?'dsync-pct-amber':'dsync-pct-red';
  set('prediction_accuracy','<span class="dsync-big-num '+accCls+'">'+pct(acc)+'</span>');
  set('prediction_totals','<span class="dsync-kpi-detail">'+money(s.prediction_received)+' received &middot; '+money(s.prediction_expected)+' invoiced</span>');
  var tpct=parseFloat(s.sales_target_pct||0);
  var tCls=tpct>=100?'dsync-pct-green':tpct>=70?'dsync-pct-amber':'dsync-pct-red';
  set('target_pct','<span class="dsync-big-num '+tCls+'">'+pct(tpct)+'</span>');
  set('target_totals','<span class="dsync-kpi-detail">'+money(s.sales_month_actual)+' actual &middot; '+money(s.sales_month_target)+' target</span>');
  set('crm_leads','<span class="dsync-metric-num">'+num(c.total_leads)+'</span>');
  set('crm_open','<span class="dsync-metric-num">'+num(c.ongoing_deals)+'</span>');
  set('crm_won','<span class="dsync-metric-num">'+num(c.won_deals)+'</span>');
  set('crm_conversion','<span class="dsync-metric-num">'+pct(c.conversion_pct)+'</span>');
  // date range label
  var p=d.period||{};
  var dateRange=p.from_date?fmtDate(p.from_date)+' – '+fmtDate(p.to_date):'Last 14 days';
  set('ar_date_range',dateRange);
  set('unrec_date_range',dateRange);
  lineChart(q('[data-chart="ar"]'),s.ar_trend,'value','#401090');
  lineChart(q('[data-chart="unreconciled"]'),s.unreconciled_trend,'value','#dc3545');
  // AR badge — last value
  var arTrend=s.ar_trend||[];
  if(arTrend.length){var el=q('#dsync-ar-badge');if(el)el.textContent=money(arTrend[arTrend.length-1].value||0);}
  var unTrend=s.unreconciled_trend||[];
  if(unTrend.length){var el2=q('#dsync-unrec-badge');if(el2)el2.textContent=num(unTrend[unTrend.length-1].value||0)+' accounts';}
  var cashRows=d.cash_bank_rows||[];
  var cashEl=q('[data-table="cash"]');
  if(cashEl){
    cashEl.innerHTML=table([
      {label:'Date',f:function(r){return'<span class="dsync-date">'+esc(fmtDate(r.date))+'</span>'}},
      {label:'Type',f:function(r){return'<span class="dsync-badge-type">'+esc(r.type||'Payment')+'</span>'}},
      {label:'Amount',f:function(r){return'<span class="dsync-money">'+money(r.amount)+'</span>'}}
    ],cashRows);
    var cb=q('#dsync-cash-count');if(cb)cb.textContent=cashRows.length+' entries';
  }
  var outRows=d.outstanding_accounts||[];
  var outEl=q('[data-table="outstanding"]');
  if(outEl){
    outEl.innerHTML=table([
      {label:'Customer',f:function(r){return'<span class="dsync-cust">'+esc(r.customer)+'</span>'}},
      {label:'Outstanding',f:function(r){return'<span class="dsync-money dsync-money-warn">'+money(r.amount)+'</span>'}},
      {label:'Days Overdue',f:function(r){
        var days=parseInt(r.days_overdue||0);
        var cls=days>30?'dsync-badge-red':days>7?'dsync-badge-amber':'dsync-badge-ok';
        return'<span class="dsync-badge-days '+cls+'">'+days+' days</span>';
      }}
    ],outRows);
    var ob=q('#dsync-out-count');if(ob)ob.textContent=outRows.length+' customers';
  }
}

function load(){
  qa('[data-kpi]').forEach(function(el){
    if(!el.innerHTML||el.innerHTML==='—'||el.innerHTML.indexOf('dsync-shimmer')!==-1){
      el.innerHTML='<span class="dsync-shimmer"></span>';
    }
  });
  frappe.call({
    method:method,
    callback:function(r){var d=r.message||{};renderSales(d);set('last_refresh',new Date().toLocaleTimeString());},
    error:function(){frappe.msgprint('Unable to load Sales Daily Sync data.');}
  });
}

var btn=q('[data-action="refresh"]');
if(btn)btn.addEventListener('click',load);
load();
setInterval(load,30*60*1000);
})();

style:
.dsync{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:1600px;margin:0 auto;padding:24px;color:#1e293b}.dsync *{box-sizing:border-box}

/* ── Header ── */
.dsync-header{background:linear-gradient(135deg,#401090 0%,#7c3aed 60%,#C060E0 100%);color:#fff;border-radius:12px;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;gap:16px}
.dsync-header-left{display:flex;align-items:center;gap:16px}
.dsync-header-right{display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.dsync-last-refresh{font-size:11px;color:rgba(255,255,255,.7);font-family:Consolas,'Courier New',monospace}
.dsync-header h2{font-size:20px;margin:0 0 2px;font-weight:800;letter-spacing:-.3px;color:#fff;}
.dsync-header p{margin:0;font-size:11.5px;opacity:.82}
.dsync-eyebrow{font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;opacity:.75;margin-bottom:3px}
.dsync-logo{width:48px;height:48px;border-radius:10px;border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.15);display:flex;align-items:center;justify-content:center;font-weight:900;font-size:16px;flex-shrink:0}
.dsync-refresh{display:inline-flex;align-items:center;gap:6px;border:1px solid rgba(255,255,255,.4);background:rgba(255,255,255,.15);color:#fff;border-radius:8px;padding:8px 14px;font-size:12px;font-weight:700;cursor:pointer;transition:background .15s}
.dsync-refresh:hover{background:rgba(255,255,255,.25)}

/* ── Alert ── */
.dsync-alert{border-radius:8px;padding:10px 14px;font-size:12px;font-weight:600;margin-bottom:20px;display:flex;align-items:center;gap:8px}
.dsync-info{background:#eff6ff;border:1px solid #bfdbfe;color:#1d4ed8}
.dsync-warn{background:#fff7ed;border:1px solid #fed7aa;color:#9a3412}
.dsync-danger{background:#fff1f2;border:1px solid #fecdd3;color:#9f1239}

/* ── Section headers ── */
.dsync-section{font-size:11px;font-weight:800;color:#401090;border-bottom:2px solid #e2e8f0;margin:28px 0 14px;padding-bottom:8px;text-transform:uppercase;letter-spacing:1px;display:flex;align-items:center;gap:7px}
.dsync-section-icon{display:inline-flex;align-items:center;opacity:.7}

/* ── KPI Cards ── */
.dsync-grid{display:grid;gap:14px}
.dsync-grid-4{grid-template-columns:repeat(4,1fr)}
.dsync-grid-3{grid-template-columns:repeat(3,1fr)}
.dsync-grid-2{grid-template-columns:repeat(2,1fr)}

.dsync-kpi-card{position:relative;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px 18px 14px;overflow:hidden;transition:all .2s}
.dsync-kpi-card:hover{border-color:#c7d2fe;transform:translateY(-2px);box-shadow:0 4px 16px rgba(0,0,0,.06)}
.dsync-kpi-accent{position:absolute;top:0;left:0;right:0;height:3px;background:var(--ka);}
.dsync-kpi-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:4px}
.dsync-kpi-label{font-size:12px;font-weight:700;color:#475569;margin-bottom:8px}
.dsync-kpi-value{min-height:36px;margin-bottom:4px}
.dsync-big-num{font-size:28px;font-weight:900;line-height:1;color:var(--ka);display:block}
.dsync-kpi-delta{min-height:18px;margin-bottom:6px}
.dsync-kpi-meta{font-size:11px;color:#94a3b8;line-height:1.4;margin-bottom:8px}
.dsync-shimmer{display:inline-block;width:80px;height:28px;border-radius:6px;background:linear-gradient(110deg,#f1f5f9 25%,#e2e8f0 50%,#f1f5f9 75%);background-size:200% 100%;animation:dsShimmer 1.4s ease-in-out infinite}
.dsync-source-tag{display:inline-block;font-size:9.5px;font-weight:600;letter-spacing:.3px;background:#f1f5f9;color:#64748b;padding:2px 8px;border-radius:20px;font-family:Consolas,'Courier New',monospace}

/* ── Delta indicators ── */
.dsync-delta{font-size:11px;font-weight:700}
.dsync-delta-up{color:#dc2626}
.dsync-delta-dn{color:#059669}
.dsync-kpi-detail{font-size:11px;color:#64748b;font-family:Consolas,'Courier New',monospace}

/* ── Pct colors ── */
.dsync-pct-green{color:#059669 !important}
.dsync-pct-amber{color:#d97706 !important}
.dsync-pct-red{color:#dc2626 !important}

/* ── Panels ── */
.dsync-panel{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px;box-shadow:0 1px 3px rgba(0,0,0,.04)}
.dsync-panel-header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:12px}
.dsync-panel-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:3px}
.dsync-panel-title{font-size:13px;font-weight:700;color:#1e293b}
.dsync-panel-badge{background:#f1f5f9;color:#475569;border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;white-space:nowrap;flex-shrink:0;font-family:Consolas,'Courier New',monospace}

/* ── Charts ── */
.dsync-chart{height:160px;margin:4px 0 0}
.dsync-chart svg{width:100%;height:100%;overflow:visible}
.dsync-axis{stroke:#e5e7eb;stroke-width:1}
.dsync-line{fill:none;stroke-width:2.5;stroke-linecap:round}
.dsync-fill{}
.dsync-chart-lbl{fill:#94a3b8;font-size:9.5px;font-family:-apple-system,sans-serif}
.dsync-chart-empty{height:100%;display:flex;align-items:center;justify-content:center;color:#94a3b8;font-size:12px;background:#fafafa;border-radius:8px}
.dsync-chart-footer{display:flex;align-items:center;justify-content:space-between;margin-top:8px;flex-wrap:wrap;gap:4px}
.dsync-chart-footer span{font-size:11px;color:#94a3b8}

/* ── Metrics panel ── */
.dsync-metrics-panel{}
.dsync-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.dsync-metric-item{background:#fafbfc;border:1px solid #e2e8f0;border-radius:10px;padding:14px;display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px}
.dsync-metric-icon{width:36px;height:36px;border-radius:9px;display:flex;align-items:center;justify-content:center}
.dsync-metric-num{font-size:26px;font-weight:900;color:#401090;display:block;line-height:1}
.dsync-metric-label{font-size:11px;color:#64748b;font-weight:600}

/* ── Tables ── */
.dsync-table-card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden}
.dsync-table-head{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #f1f5f9;background:#fafbfc}
.dsync-table-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:2px}
.dsync-table-title{font-size:13px;font-weight:700;color:#1e293b}
.dsync-table-badge{background:#f1f5f9;color:#475569;border-radius:20px;padding:4px 10px;font-size:11px;font-weight:700;white-space:nowrap}
.dsync-table-footer{padding:10px 18px;border-top:1px solid #f1f5f9;font-size:10px;color:#94a3b8;font-family:Consolas,'Courier New',monospace}
.dsync table{width:100%;border-collapse:collapse}
.dsync th{background:#f8fafc;color:#475569;padding:9px 14px;font-size:10px;text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid #e2e8f0;white-space:nowrap}
.dsync td{padding:10px 14px;border-bottom:1px solid #f8fafc;font-size:12.5px;color:#334155}
.dsync th:not(:first-child),.dsync td:not(:first-child){text-align:right}
.dsync tr:last-child td{border-bottom:none}
.dsync tbody tr:hover td{background:#fafbff}
.dsync-empty{padding:28px;text-align:center;color:#94a3b8;font-size:12px}
.dsync-tbl-loading{padding:28px;text-align:center}
.dsync-spin{display:inline-block;width:20px;height:20px;border:3px solid #e2e8f0;border-top-color:#401090;border-radius:50%;animation:dsSpin .7s linear infinite}
.dsync-date{color:#475569;font-family:Consolas,'Courier New',monospace;font-size:12px}
.dsync-cust{font-weight:600;color:#1e293b}
.dsync-money{font-family:Consolas,'Courier New',monospace;font-weight:700;color:#1e293b}
.dsync-money-warn{color:#dc2626}
.dsync-badge-type{background:#eff6ff;color:#2563eb;border-radius:20px;padding:2px 8px;font-size:10.5px;font-weight:600}
.dsync-badge-days{border-radius:20px;padding:2px 8px;font-size:10.5px;font-weight:700}
.dsync-badge-ok{background:#f0fdf4;color:#059669}
.dsync-badge-amber{background:#fffbeb;color:#d97706}
.dsync-badge-red{background:#fff1f2;color:#dc2626}

/* ── Footer ── */
.dsync-footer{display:flex;align-items:center;justify-content:space-between;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px 18px;margin-top:24px;font-size:11px;color:#64748b;flex-wrap:wrap;gap:8px}

/* ── Animations ── */
@keyframes dsShimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}
@keyframes dsSpin{to{transform:rotate(360deg)}}

@media(max-width:1200px){.dsync-grid-4{grid-template-columns:repeat(2,1fr)}.dsync-metrics{grid-template-columns:repeat(2,1fr)}}
@media(max-width:768px){.dsync{padding:12px}.dsync-header{flex-direction:column;align-items:flex-start}.dsync-grid-4,.dsync-grid-3,.dsync-grid-2{grid-template-columns:1fr}}

script:
/* ===== SALES TARGET DASHBOARD ===== */
(function() {
var rootEl = root_element.querySelector('.sd-dash');

    var API = 'cannabis_management.api.jamie.';
    var currentPeriod = 'weekly';
    var currentMatrix = 'weekly';
    var currentView   = 'value';
    var matrixCache   = {};
    var arMatrixData  = null;

    var hour = new Date().getHours();
    var ge = rootEl.querySelector('.sd-greeting');
    if (ge) ge.textContent = hour < 12 ? 'good morning' : hour < 17 ? 'good afternoon' : 'good evening';

    window.salesDash = {
        reload:      function () { loadAll(currentPeriod); },
        exportExcel: function () { downloadCSV(); },
    };

    // ── Formatters ────────────────────────────────────────────────
    function fmtCurrency(val) {
        return '$ ' + parseFloat(val || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }
    function fmtQty(val) {
        return parseFloat(val || 0).toLocaleString(undefined, { maximumFractionDigits: 2 });
    }

    // ── Shimmer helpers ───────────────────────────────────────────
    function shimmerKpi(id) {
        var el = rootEl.querySelector('#' + id);
        if (el) { el.classList.remove('loaded', 'error'); el.innerHTML = '<span class="sd-loader"></span>'; }
    }
    function shimmerEl(id) {
        var el = rootEl.querySelector('#' + id);
        if (el) el.innerHTML = '<div class="sd-loading"><div class="sd-spinner"></div></div>';
    }

    // ── Period bar ────────────────────────────────────────────────
    function setPeriodUI(period) {
        var labels = { daily: 'Today', weekly: 'This Week', monthly: 'This Month', last_month: 'Last Month' };
        rootEl.querySelectorAll('.sd-period-btn').forEach(function (btn) {
            btn.classList.toggle('active', btn.dataset.period === period);
        });
        var lbl = rootEl.querySelector('#sd-period-label');
        if (lbl) lbl.textContent = labels[period] || period;
        var kl = rootEl.querySelector('#sd-target-label');
        if (kl) kl.textContent = 'Pro-rated Target · ' + (labels[period] || period);
    }

    // ── Matrix toggle ─────────────────────────────────────────────
    function setMatrixUI(mtx) {
        currentMatrix = mtx;
        rootEl.querySelectorAll('.sd-mtx-btn').forEach(function (btn) {
            btn.classList.toggle('active', btn.dataset.mtx === mtx);
        });
        var title = rootEl.querySelector('#sd-matrix-title');
        if (title) {
            var labels = { monthly: 'Monthly', weekly: 'Weekly', daily: 'Daily' };
            title.textContent = (labels[mtx] || 'Weekly') + ' Revenue Matrix';
        }
        if (matrixCache[mtx]) renderMatrix('sd-matrix', matrixCache[mtx]);
        if (arMatrixData) {
            renderArMatrix('sd-ar-matrix', arMatrixData, arMatrixData.columns);
        }
    }

    // ── Value / Qty toggle ────────────────────────────────────────
    function setViewUI(view) {
        currentView = view;
        rootEl.querySelectorAll('.sd-view-btn').forEach(function (btn) {
            btn.classList.toggle('active', btn.dataset.view === view);
        });
        if (matrixCache[currentMatrix]) renderMatrix('sd-matrix', matrixCache[currentMatrix]);
    }

    // ── Matrix renderer (company-wise, fixed IG lists) ─────────
    function renderMatrix(containerId, matrix) {
        var el = rootEl.querySelector('#' + containerId);
        if (!el) return;
        if (!matrix || !matrix.columns || !matrix.columns.length) {
            el.innerHTML = '<p class="sd-empty">No data for this period.</p>';
            return;
        }

        var isQty   = currentView === 'qty';
        var cols    = matrix.columns;
        var showAvg = currentMatrix === 'weekly';
        var AVG     = 'Avg (8 Wks)';
        var targetDiv, targetLabel;
        if (currentMatrix === 'monthly')    { targetDiv = 1;  targetLabel = 'Monthly Target'; }
        else if (currentMatrix === 'daily') { targetDiv = 20; targetLabel = 'Daily Target'; }
        else                                { targetDiv = 4;  targetLabel = 'Weekly Target'; }

        var pByIG = {};
        (matrix.products || []).forEach(function(p) { pByIG[p.item_group] = p; });
        var cig = matrix.company_ig_map || {};

        // ── Fixed company + IG definitions ──────────────────────────
        // m: null = catch-all "Others" (everything not in any named row for this company)
        var CDEFS = [
          { label:'Motley Terpz', cos:['Motley Terpz','MTPZ'],
            tot:'motley_totals', avg:'avg_motley',
            color:'#7c3aed', bg:'#f5f3ff', border:'#7c3aed',
            igs:[
              {d:'Packaged Goods', m:['Packaged goods','Packaged Goods']},
              {d:'Rosin',          m:['Rosins','Rosin','Total Rosin']},
              {d:'Bubble Cured',   m:['Bubble Cured']},
              {d:'Static',         m:['Static']},
              {d:'Pre Rolls',      m:['Pre Rolls','Pre-Rolls','Pre Roll']},
              {d:'Gummies',        m:['Gummies']},
              {d:'Others',         m:null},
            ]},
          { label:'TSBC Ranch', cos:['TSBC Ranch'],
            tot:'tsbc_totals', avg:'avg_tsbc',
            color:'#059669', bg:'#f0fdf4', border:'#059669',
            igs:[
              // Backend child_to_parent rollup aggregates all children
              // (Fresh Frozen, Fresh Frozen - SHO, Fresh Frozen - BHO) into Fresh Frozen Main
              {d:'Fresh Frozen Main', m:['Fresh Frozen Main','Fresh Frozen - Main',
                                        'Fresh Frozen','Fresh Frozen - SHO','Fresh Frozen - BHO',
                                        'Frozen']},
            ]},
          { label:'Master Touch Manufacturing', cos:['Master Touch Manufacturing'],
            tot:'mtm_totals', avg:'avg_mtm',
            color:'#2563eb', bg:'#eef2ff', border:'#2563eb',
            igs:[
              {d:'Rosin',        m:['Rosins','Rosin','Total Rosin']},
              {d:'Bubble Cured', m:['Bubble Cured']},
              {d:'Static',       m:['Static']},
              {d:'Pre Rolls',    m:['Pre Rolls','Pre-Rolls','Pre Roll']},
              {d:'Gummies',      m:['Gummies']},
              {d:'Others',       m:null},
            ]},
          { label:'LA Canna', cos:['LA Canna Distro'],
            tot:'la_canna_totals', avg:'avg_la_canna',
            color:'#0891b2', bg:'#ecfeff', border:'#0891b2',
            igs:[
              {d:'Packaged Goods', m:['Packaged goods','Packaged Goods']},
            ]},
        ];

        // Helper: get rev/qty for a set of companies + match list, one column
        function getVal(coNames, matchSet, col) {
            var rev = 0, qty = 0;
            coNames.forEach(function(cn) {
                var cd = cig[cn] || {};
                Object.keys(cd).forEach(function(ig) {
                    var inSet = matchSet === null ? true : matchSet.some(function(m){
                        return m.toLowerCase() === ig.toLowerCase();
                    });
                    if (inSet) {
                        rev += ((cd[ig][col]||{}).rev)||0;
                        qty += ((cd[ig][col]||{}).qty)||0;
                    }
                });
            });
            return {rev:rev, qty:qty};
        }

        // For "Others" (m:null): exclude everything in the named rows
        function getOthersVal(coNames, namedSets, col) {
            var rev = 0, qty = 0;
            var excluded = {};
            namedSets.forEach(function(ms) {
                if (!ms) return;
                ms.forEach(function(m){ excluded[m.toLowerCase()] = 1; });
            });
            coNames.forEach(function(cn) {
                var cd = cig[cn] || {};
                Object.keys(cd).forEach(function(ig) {
                    if (!excluded[ig.toLowerCase()]) {
                        rev += ((cd[ig][col]||{}).rev)||0;
                        qty += ((cd[ig][col]||{}).qty)||0;
                    }
                });
            });
            return {rev:rev, qty:qty};
        }

        // Target lookup: find first m-match in pByIG that has a target
        function getTarget(matchList) {
            if (!matchList) return null;
            for (var i=0; i<matchList.length; i++) {
                var p = pByIG[matchList[i]];
                if (p && p.has_target) return p;
            }
            return null;
        }

        function cc(actual, target) {
            if (!target || target <= 0) return '';
            var r = actual / target;
            return r>=1 ? 'sd-cell-green' : r>=0.7 ? 'sd-cell-amber' : actual > 0 ? 'sd-cell-red' : '';
        }

        // ── Header ────────────────────────────────────────────────
        var html = '<table class="sd-matrix"><thead><tr>';
        html += '<th class="sd-matrix-th-product">Company / Item Group</th>';
        html += '<th class="sd-matrix-th-static">Target Units</th>';
        html += '<th class="sd-matrix-th-static">Avg Price</th>';
        html += '<th class="sd-matrix-th-static">' + (isQty?'Target Units':targetLabel) + '</th>';
        cols.forEach(function(c){ html += '<th class="sd-matrix-th-period">' + frappe.utils.escape_html(c) + '</th>'; });
        if (showAvg) html += '<th class="sd-matrix-th-avg">' + AVG + '</th>';
        html += '</tr></thead><tbody>';

        var grandTotals = {}; cols.forEach(function(c){ grandTotals[c]=0; });
        var grandAvg = 0;

        CDEFS.forEach(function(co) {
            var coTotals = matrix[co.tot] || {};
            var coAvg    = matrix[co.avg] || 0;
            cols.forEach(function(c){ grandTotals[c] += coTotals[c]||0; });
            grandAvg += coAvg;

            // Precompute "named" match sets for Others exclusion
            var namedSets = co.igs.filter(function(r){return r.m!==null;}).map(function(r){return r.m;});

            // Compute company-level target sums (exclude catch-all Others)
            var coTargetUnits = 0, coTargetRev = 0;
            co.igs.forEach(function(igDef) {
                if (!igDef.m) return;
                var p = getTarget(igDef.m);
                if (p) {
                    coTargetUnits += (p.target_units   || 0) / targetDiv;
                    coTargetRev   += (p.monthly_target || 0) / targetDiv;
                }
            });

            // ── Company header row ──────────────────────────────
            html += '<tr style="background:' + co.bg + ';border-top:2px solid ' + co.border + ';">';
            html += '<td class="sd-matrix-product" style="font-weight:800;color:' + co.color + ';border-right:1px solid #e2e8f0;">'
                  + frappe.utils.escape_html(co.label) + '</td>';
            html += '<td class="sd-matrix-num" style="font-weight:700;color:' + co.color + ';">'
                  + (coTargetUnits > 0 ? fmtQty(coTargetUnits) : '—') + '</td>';
            html += '<td class="sd-matrix-num">—</td>';
            if (isQty) {
                html += '<td class="sd-matrix-num" style="font-weight:700;color:' + co.color + ';">'
                      + (coTargetUnits > 0 ? fmtQty(coTargetUnits) : '—') + '</td>';
            } else {
                html += '<td class="sd-matrix-num" style="font-weight:700;color:' + co.color + ';">'
                      + (coTargetRev > 0 ? fmtCurrency(coTargetRev) : '—') + '</td>';
            }
            cols.forEach(function(c) {
                var v = coTotals[c]||0;
                html += '<td class="sd-matrix-num" style="font-weight:700;color:' + co.color + ';">'
                      + (v > 0 ? fmtCurrency(v) : '—') + '</td>';
            });
            if (showAvg) html += '<td class="sd-matrix-num sd-matrix-avg" style="color:' + co.color + ';">'
                               + (coAvg > 0 ? fmtCurrency(coAvg) : '—') + '</td>';
            html += '</tr>';

            // ── Item group sub-rows ─────────────────────────────
            co.igs.forEach(function(igDef) {
                var p = getTarget(igDef.m);
                var tgtRev   = (p && p.monthly_target) ? p.monthly_target / targetDiv : 0;
                var tgtUnits = (p && p.target_units)   ? p.target_units   / targetDiv : 0;

                html += '<tr>';
                html += '<td class="sd-matrix-product" style="padding-left:24px;font-weight:500;color:#475569;">'
                      + frappe.utils.escape_html(igDef.d) + '</td>';
                html += '<td class="sd-matrix-num">' + (tgtUnits ? fmtQty(tgtUnits) : '—') + '</td>';
                html += '<td class="sd-matrix-num">' + (p && p.avg_price ? fmtCurrency(p.avg_price) : '—') + '</td>';
                if (isQty) {
                    html += '<td class="sd-matrix-num sd-matrix-target-rev">' + (tgtUnits ? fmtQty(tgtUnits) : '—') + '</td>';
                } else {
                    html += '<td class="sd-matrix-num sd-matrix-target-rev">' + (tgtRev ? fmtCurrency(tgtRev) : '—') + '</td>';
                }
                cols.forEach(function(col) {
                    var vals = igDef.m === null
                        ? getOthersVal(co.cos, namedSets, col)
                        : getVal(co.cos, igDef.m, col);
                    if (isQty) {
                        html += '<td class="sd-matrix-num ' + cc(vals.qty, tgtUnits) + '">'
                              + (vals.qty > 0 ? fmtQty(vals.qty) : '—') + '</td>';
                    } else {
                        var ct = (p && p.cell_targets) ? (p.cell_targets[col]||0) : 0;
                        html += '<td class="sd-matrix-num ' + cc(vals.rev, ct) + '">'
                              + (vals.rev > 0 ? fmtCurrency(vals.rev) : '—') + '</td>';
                    }
                });
                if (showAvg) {
                    var igRevs = cols.map(function(c){
                        return igDef.m === null
                            ? getOthersVal(co.cos, namedSets, c).rev
                            : getVal(co.cos, igDef.m, c).rev;
                    });
                    var igAvg = igRevs.reduce(function(s,v){return s+v;},0) / (cols.length||1);
                    html += '<td class="sd-matrix-num sd-matrix-avg">' + (igAvg > 0 ? fmtCurrency(igAvg) : '—') + '</td>';
                }
                html += '</tr>';
            });
        });

        // ── Compute target sums across all displayed rows ─────────
        var totalTargetUnits = 0, totalTargetRev = 0;
        CDEFS.forEach(function(co) {
            co.igs.forEach(function(igDef) {
                if (!igDef.m) return;   // skip catch-all "Others"
                var p = getTarget(igDef.m);
                if (p) {
                    totalTargetUnits += (p.target_units   || 0) / targetDiv;
                    totalTargetRev   += (p.monthly_target || 0) / targetDiv;
                }
            });
        });

        // ── Grand Total ───────────────────────────────────────────
        html += '<tr class="sd-matrix-foot-grand-total"><td class="sd-matrix-product sd-matrix-foot-label">Total</td>';
        html += '<td class="sd-matrix-num sd-matrix-total-cell">' + (totalTargetUnits > 0 ? fmtQty(totalTargetUnits) : '—') + '</td>';
        html += '<td class="sd-matrix-num">—</td>';
        html += '<td class="sd-matrix-num sd-matrix-total-cell">' + (totalTargetRev > 0 ? fmtCurrency(totalTargetRev) : '—') + '</td>';
        cols.forEach(function(c){
            var v = grandTotals[c]||0;
            html += '<td class="sd-matrix-num sd-matrix-total-cell">' + (v > 0 ? fmtCurrency(v) : '—') + '</td>';
        });
        if (showAvg) html += '<td class="sd-matrix-num sd-matrix-avg sd-matrix-total-cell">'
                           + (grandAvg > 0 ? fmtCurrency(grandAvg) : '—') + '</td>';
        html += '</tr></tbody></table>';
        el.innerHTML = html;
    }

    // ── AR Matrix renderer ────────────────────────────────────────
    function renderArMatrix(containerId, ar, cols) {
        var el = rootEl.querySelector('#' + containerId);
        if (!el) return;
        if (!ar || !cols || !cols.length) {
            el.innerHTML = '<p class="sd-empty">AR data loading…</p>';
            return;
        }

        var bal  = ar.balances   || {};
        var coll = ar.collected  || {};
        var pace = ar.pace_by_col || {};
        var avg  = ar.avg        || {};

        function arTd(v, cls) {
            return '<td class="sd-matrix-num' + (cls ? ' ' + cls : '') + '">'
                 + (v > 0 ? fmtCurrency(v) : '—') + '</td>';
        }

        var html = '<table class="sd-matrix"><thead><tr>';
        html += '<th class="sd-matrix-th-product">AR Category</th>';
        html += '<th class="sd-matrix-th-static">Outstanding Balance</th>';
        html += '<th class="sd-matrix-th-static">Monthly Pace</th>';
        cols.forEach(function(c) { html += '<th class="sd-matrix-th-period">' + frappe.utils.escape_html(c) + '</th>'; });
        html += '<th class="sd-matrix-th-avg">Total Collected</th>';
        html += '</tr></thead><tbody>';

        // ── Total AR (grayed, reference only) ─────────────────────
        html += '<tr style="opacity:.5">';
        html += '<td class="sd-matrix-product" style="color:#94a3b8;text-decoration:line-through;">Total AR</td>';
        html += '<td class="sd-matrix-num" style="text-decoration:line-through;">' + fmtCurrency(bal.total||0) + '</td>';
        html += '<td class="sd-matrix-num">—</td>';
        cols.forEach(function(c){ html += arTd((coll.total||{})[c]||0); });
        html += arTd(avg.total||0);
        html += '</tr>';

        // ── Legacy AR balance row ─────────────────────────────────
        html += '<tr class="sd-ar-legacy">';
        html += '<td class="sd-matrix-product sd-ar-label-legacy">Legacy AR'
              + ' <span class="sd-ar-badge-legacy">pre-Jun 1</span></td>';
        html += '<td class="sd-matrix-num" style="color:#dc2626;font-weight:800;">' + fmtCurrency(bal.legacy||0) + '</td>';
        html += '<td class="sd-matrix-num sd-matrix-target-rev">' + fmtCurrency(ar.legacy_monthly_target||400000) + '/mo</td>';
        cols.forEach(function(c){ html += arTd(0); });
        html += arTd(0);
        html += '</tr>';

        // ── Total Legacy AR Collected (monthly) ───────────────────
        html += '<tr style="background:#fff5f5;">';
        html += '<td class="sd-matrix-product" style="padding-left:20px;color:#dc2626;font-weight:600;">'
              + 'Total Legacy AR Collected</td>';
        html += '<td class="sd-matrix-num">—</td>';
        html += '<td class="sd-matrix-num sd-matrix-target-rev">' + fmtCurrency(ar.legacy_monthly_target||400000) + '/mo</td>';
        var legacyTotal = 0;
        cols.forEach(function(c) {
            var v = (coll.legacy||{})[c] || 0;
            var t = pace[c] || 0;
            var cls = '';
            if (v > 0 && t > 0) { var r = v/t; cls = r>=1 ? 'sd-cell-green' : r>=0.5 ? 'sd-cell-amber' : 'sd-cell-red'; }
            legacyTotal += v;
            html += '<td class="sd-matrix-num ' + cls + '">' + (v > 0 ? fmtCurrency(v) : '—') + '</td>';
        });
        html += arTd(legacyTotal);
        html += '</tr>';

        // ── New AR (Jun 1 onwards) ────────────────────────────────
        html += '<tr class="sd-ar-good">';
        html += '<td class="sd-matrix-product sd-ar-label-good">New AR'
              + ' <span class="sd-ar-badge-good">Jun 1+</span></td>';
        html += '<td class="sd-matrix-num" style="color:#059669;font-weight:700;">' + fmtCurrency(bal.new_ar||0) + '</td>';
        html += '<td class="sd-matrix-num">—</td>';
        var newTotal = 0;
        cols.forEach(function(c) {
            var v = (coll.new_ar||{})[c] || 0;
            newTotal += v;
            html += '<td class="sd-matrix-num' + (v > 0 ? ' sd-cell-green' : '') + '">'
                  + (v > 0 ? fmtCurrency(v) : '—') + '</td>';
        });
        html += arTd(newTotal);
        html += '</tr>';

        html += '</tbody></table>';
        el.innerHTML = html;
    }

    // ── Excel export ──────────────────────────────────────────────
    function downloadCSV() {
        var matrix = matrixCache[currentMatrix];
        if (!matrix || !matrix.columns || !matrix.products) {
            frappe.msgprint('No data to export yet.'); return;
        }

        var isQty   = currentView === 'qty';
        var cols    = matrix.columns;
        var showAvg = currentMatrix === 'weekly';
        var FF_KEY  = 'Fresh Frozen';

        var targetDiv, targetLabel;
        if (currentMatrix === 'monthly')    { targetDiv = 1;  targetLabel = 'Monthly Target'; }
        else if (currentMatrix === 'daily') { targetDiv = 20; targetLabel = 'Daily Target'; }
        else                                { targetDiv = 4;  targetLabel = 'Weekly Target'; }

        var motleyProducts = matrix.products.filter(function (p) { return p.item_group !== FF_KEY; });
        var ffProduct      = matrix.products.find(function (p)   { return p.item_group === FF_KEY; }) || null;

        var motleyTargetRev = 0, motleyTargetUnits = 0;
        motleyProducts.forEach(function (p) {
            motleyTargetRev   += p.monthly_target ? p.monthly_target / targetDiv : 0;
            motleyTargetUnits += p.target_units   ? p.target_units   / targetDiv : 0;
        });

        var tsbcMonthly     = matrix.tsbc_monthly_target || 400000;
        var tsbcTargetRev   = tsbcMonthly / targetDiv;
        var tsbcTargetUnits = 2000 / targetDiv;
        var ffTargetRev     = ffProduct ? (ffProduct.monthly_target ? ffProduct.monthly_target / targetDiv : 0) : 0;
        var ffTargetUnits   = ffProduct ? (ffProduct.target_units   ? ffProduct.target_units   / targetDiv : 0) : 0;

        var avgActuals = {}, avgUnits = {};
        if (showAvg) {
            matrix.products.forEach(function (p) {
                var rSum = 0, qSum = 0;
                cols.forEach(function (c) { rSum += p.actuals[c] || 0; qSum += (p.units && p.units[c]) || 0; });
                avgActuals[p.item_group] = cols.length ? rSum / cols.length : 0;
                avgUnits[p.item_group]   = cols.length ? qSum / cols.length : 0;
            });
        }

        // ── Helpers ───────────────────────────────────────────────
        function he(s) {
            return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
        }
        function fmtNum(v) {
            if (!v || v <= 0) return '';
            return isQty
                ? parseFloat(v).toLocaleString(undefined, { maximumFractionDigits: 2 })
                : '$ ' + parseFloat(v).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        }
        function fmtTgt(v) { return fmtNum(v); }

        // Cell builders
        function th(txt, extra) {
            return '<td class="hdr"' + (extra || '') + '>' + he(txt) + '</td>';
        }
        function td(txt, cls, extra) {
            return '<td' + (cls ? ' class="' + cls + '"' : '') + (extra || '') + '>' + he(txt) + '</td>';
        }
        function tdNum(v, cls) {
            var s = fmtNum(v);
            return '<td class="num' + (cls ? ' ' + cls : '') + '">' + he(s) + '</td>';
        }
        function tdTgt(v) {
            return '<td class="num tgt">' + he(fmtTgt(v)) + '</td>';
        }
        function blank(n) { var s = ''; for (var i=0;i<n;i++) s += '<td></td>'; return s; }

        // ── Build HTML ────────────────────────────────────────────
        var periodLabel = currentMatrix.charAt(0).toUpperCase() + currentMatrix.slice(1);
        var dateStr     = new Date().toLocaleDateString(undefined, { year:'numeric', month:'short', day:'numeric' });
        var tgtColLabel = isQty ? targetLabel.replace('Target','Target Units') : targetLabel;
        var numDataCols = cols.length + (showAvg ? 1 : 0);

        var html = [
            '<html xmlns:o="urn:schemas-microsoft-com:office:office"',
            '      xmlns:x="urn:schemas-microsoft-com:office:excel"',
            '      xmlns="http://www.w3.org/TR/REC-html40">',
            '<head><meta charset="UTF-8">',
            '<!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet>',
            '<x:Name>Sales Target</x:Name>',
            '<x:WorksheetOptions><x:FreezePanes/><x:FrozenNoSplit/>',
            '<x:SplitHorizontal>2</x:SplitHorizontal><x:TopRowBottomPane>2</x:TopRowBottomPane>',
            '</x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]-->',
            '<style>',
            'body{font-family:Calibri,Arial,sans-serif;font-size:11pt;}',
            'table{border-collapse:collapse;width:100%;}',
            'td,th{border:1px solid #d1d5db;padding:5px 10px;vertical-align:middle;}',
            /* Title row */
            '.title{background:#1e293b;color:#fff;font-size:14pt;font-weight:700;border:none;padding:10px 14px;}',
            '.sub{background:#334155;color:#94a3b8;font-size:9pt;border:none;padding:4px 14px;}',
            /* Header */
            '.hdr{background:#1e293b;color:#fff;font-weight:700;font-size:10pt;text-align:center;white-space:nowrap;}',
            '.hdr-left{text-align:left;}',
            /* Numbers */
            '.num{text-align:right;font-family:"Courier New",monospace;font-size:10pt;white-space:nowrap;}',
            '.tgt{background:#f5f0ff;font-weight:600;}',
            /* Data cell colors */
            '.green{color:#065f46;background:#d1fae5;}',
            '.red{color:#991b1b;background:#fee2e2;}',
            '.amber{color:#92400e;background:#fef3c7;}',
            /* Section rows */
            '.tgt-motley td{background:#ede9fe;font-weight:700;}',
            '.tgt-motley .lbl{color:#6d28d9;}',
            '.motley-total td{background:#f1f5f9;font-weight:700;border-top:2px solid #7c3aed;}',
            '.motley-total .lbl{color:#475569;}',
            '.sep td{background:#fff;border:none;height:8px;}',
            '.ff-row td{background:#f0fdf4;}',
            '.tgt-tsbc td{background:#dcfce7;font-weight:700;}',
            '.tgt-tsbc .lbl{color:#15803d;}',
            '.tsbc-row td{background:#f0fdf4;font-weight:700;border-top:2px solid #059669;}',
            '.tsbc-row .lbl{color:#065f46;}',
            /* Label cells */
            '.lbl{font-weight:600;white-space:nowrap;}',
            '.dim{color:#94a3b8;}',
            '</style></head><body>',
        ].join('\n');

        html += '<table>';

        // ── Title rows ────────────────────────────────────────────
        var totalCols = 4 + cols.length + (showAvg ? 1 : 0);
        html += '<tr><td class="title" colspan="' + totalCols + '">Sales Target Dashboard &mdash; ' + he(periodLabel) + ' View</td></tr>';
        html += '<tr><td class="sub" colspan="' + totalCols + '">Exported ' + he(dateStr) + ' &nbsp;&bull;&nbsp; ' + he(currentView === 'qty' ? 'Quantity View' : 'Revenue View') + '</td></tr>';
        html += '<tr><td colspan="' + totalCols + '" style="border:none;height:4px;background:#fff;"></td></tr>';

        // ── Header row ────────────────────────────────────────────
        html += '<tr>';
        html += th('Item Group', ' class="hdr hdr-left"');
        html += th('Target Units');
        html += th('Avg Price');
        html += th(tgtColLabel);
        cols.forEach(function (c) { html += th(c); });
        if (showAvg) html += th('Avg (8 Wks)');
        html += '</tr>';

        // ── Motley product rows ───────────────────────────────────
        motleyProducts.forEach(function (p, i) {
            var bg = i % 2 === 0 ? '' : ' style="background:#f9fafb;"';
            html += '<tr' + bg + '>';
            html += td(p.item_group, 'lbl');
            var dU = p.target_units ? p.target_units / targetDiv : 0;
            html += td(dU ? Math.round(dU).toLocaleString() : '—', 'num dim');
            html += td(p.avg_price ? ('$' + parseFloat(p.avg_price).toFixed(2)) : '—', 'num dim');
            if (isQty) {
                var tU = p.target_units ? p.target_units / targetDiv : 0;
                html += td(tU ? Math.round(tU).toLocaleString() : '—', 'num tgt');
            } else {
                var tR = p.monthly_target ? p.monthly_target / targetDiv : 0;
