        html += '</tr>';

        // ── Separator ──────────────────────────────
        html += '<tr class="sep"><td colspan="' + totalCols + '"></td></tr>';

        // ── Fresh Frozen row ──────────────────────────
        if (ffProduct) {
            html += '<tr class="ff-row">';
            html += td(FF_KEY, 'lbl');
            var ffU = ffProduct.target_units ? ffProduct.target_units / targetDiv : 0;
            html += td(ffU ? Math.round(ffU).toLocaleString() : '—', 'num dim');
            html += td('—', 'num dim');
            var ffTV = isQty ? (ffTargetUnits ? Math.round(ffTargetUnits).toLocaleString() : '—')
                             : (ffTargetRev   ? ('$ ' + ffTargetRev.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})) : '—');
            html += td(ffTV, 'num tgt');
            cols.forEach(function (col) {
                var val = isQty ? ((ffProduct.units && ffProduct.units[col])||0) : (ffProduct.actuals[col]||0);
                var tgt = (ffProduct.cell_targets && ffProduct.cell_targets[col]) || 0;
                var cls = '';
                if (val > 0 && tgt > 0) { var r = val/tgt; cls = r>=1 ? 'green' : r>=0.7 ? 'amber' : 'red'; }
                html += td(val > 0 ? fmtNum(val) : '—', 'num' + (cls ? ' ' + cls : ''));
            });
            if (showAvg) {
                var ffAvg = isQty ? (avgUnits[FF_KEY]||0) : (avgActuals[FF_KEY]||0);
                html += td(ffAvg > 0 ? fmtNum(ffAvg) : '—', 'num');
            }
            html += '</tr>';
        }

        // ── TSBC (target + actuals merged) ────────────────────
        html += '<tr class="tsbc-row">';
        html += td('TSBC', 'lbl');
        html += td('—', 'num dim'); html += td('—', 'num dim');
        var ttV = isQty ? (ffTargetUnits ? Math.round(ffTargetUnits).toLocaleString() : '—')
                        : (ffTargetRev   ? ('$ ' + ffTargetRev.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})) : '—');
        html += td(ttV, 'num tgt');
        cols.forEach(function (c) {
            var v   = ffProduct ? (isQty ? ((ffProduct.units && ffProduct.units[c]) || 0) : (ffProduct.actuals[c] || 0)) : ((matrix.tsbc_totals && matrix.tsbc_totals[c]) || 0);
            var tgt = ffProduct ? ((ffProduct.cell_targets && ffProduct.cell_targets[c]) || 0) : 0;
            var cls = '';
            if (v > 0 && tgt > 0) { var r = v/tgt; cls = r>=1 ? 'green' : r>=0.7 ? 'amber' : 'red'; }
            html += td(v > 0 ? fmtNum(v) : '—', 'num' + (cls ? ' ' + cls : ''));
        });
        if (showAvg) {
            var ffAvgEx = isQty ? (avgUnits[FF_KEY] || 0) : (avgActuals[FF_KEY] || 0);
            html += td(ffAvgEx > 0 ? fmtNum(ffAvgEx) : '—', 'num');
        }
        html += '</tr>';

        // ── Separator ──────────────────────────────
        html += '<tr class="sep"><td colspan="' + totalCols + '"></td></tr>';

        // ── Master Touch Manufacturing ──────────────
        html += '<tr style="background:#eef2ff;">';
        html += td('Master Touch Manufacturing', 'lbl');
        html += td('—', 'num dim'); html += td('—', 'num dim'); html += td('—', 'num dim');
        cols.forEach(function (c) {
            var v = (matrix.mtm_totals && matrix.mtm_totals[c]) || 0;
            html += td(v > 0 ? fmtNum(v) : '—', 'num');
        });
        if (showAvg) html += td(matrix.avg_mtm > 0 ? fmtNum(matrix.avg_mtm) : '—', 'num');
        html += '</tr>';

        // ── LA Canna ────────────────────────────────
        html += '<tr style="background:#eef2ff;">';
        html += td('LA Canna', 'lbl');
        html += td('—', 'num dim'); html += td('—', 'num dim'); html += td('—', 'num dim');
        cols.forEach(function (c) {
            var v = (matrix.la_canna_totals && matrix.la_canna_totals[c]) || 0;
            html += td(v > 0 ? fmtNum(v) : '—', 'num');
        });
        if (showAvg) html += td(matrix.avg_la_canna > 0 ? fmtNum(matrix.avg_la_canna) : '—', 'num');
        html += '</tr>';

        // ── Separator ──────────────────────────────
        html += '<tr class="sep"><td colspan="' + totalCols + '"></td></tr>';

        // ── Total ───────────────────────────────────
        html += '<tr style="background:#1e293b;color:#fff;font-weight:700;">';
        html += '<td class="lbl" style="color:#fff;padding:7px 12px;">Total</td>';
        html += '<td></td><td></td><td></td>';
        cols.forEach(function (c) {
            var motley  = (matrix.motley_totals   && matrix.motley_totals[c])   || 0;
            var tsbc    = ffProduct ? (ffProduct.actuals[c] || 0) : ((matrix.tsbc_totals && matrix.tsbc_totals[c]) || 0);
            var mtm     = (matrix.mtm_totals      && matrix.mtm_totals[c])      || 0;
            var lacanna = (matrix.la_canna_totals && matrix.la_canna_totals[c]) || 0;
            var total   = motley + tsbc + mtm + lacanna;
            html += '<td style="text-align:right;font-family:Courier New,monospace;padding:7px 12px;color:#fff;">' + (total > 0 ? fmtNum(total) : '—') + '</td>';
        });
        if (showAvg) {
            var avgT = (matrix.avg_motley||0)+(matrix.avg_tsbc||0)+(matrix.avg_mtm||0)+(matrix.avg_la_canna||0);
            html += '<td style="text-align:right;font-family:Courier New,monospace;padding:7px 12px;color:#fff;">' + (avgT > 0 ? fmtNum(avgT) : '—') + '</td>';
        }
        html += '</tr>';

        html += '</table></body></html>';

        // ── Download ──────────────────────────────────────────────
        var blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8;' });
        var url  = URL.createObjectURL(blob);
        var a    = document.createElement('a');
        a.href   = url;
        a.download = 'Sales_Target_' + periodLabel + '_' + new Date().toISOString().slice(0,10) + '.xls';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }

    // ── Data loading ──────────────────────────────────────────────
    function loadAll(period) {
        setPeriodUI(period);
        var territory = (rootEl.querySelector('#sd-territory') || {}).value || '';

        ['sd-kpi-target','sd-kpi-actual','sd-kpi-variance','sd-kpi-pending'].forEach(shimmerKpi);
        shimmerEl('sd-matrix');

        frappe.call({
            method: API + 'get_sales_dashboard_data',
            args: { period: period, territory: territory || null },
            callback: function (r) {
                if (!r.message) return;
                var d = r.message, k;
                k = rootEl.querySelector('#sd-kpi-target');
                if (k) { k.textContent = fmtCurrency(d.total_target_rev); k.classList.add('loaded'); }
                k = rootEl.querySelector('#sd-kpi-target-sub');
                if (k) k.textContent = (d.products.length || 0) + ' product line' + (d.products.length !== 1 ? 's' : '') + ' · FY ' + (d.fiscal_year || '—');
                k = rootEl.querySelector('#sd-kpi-actual');
                if (k) { k.textContent = fmtCurrency(d.total_actual_rev); k.classList.add('loaded'); }
                k = rootEl.querySelector('#sd-kpi-actual-sub');
                if (k) k.textContent = d.from_date + ' → ' + d.to_date;
                k = rootEl.querySelector('#sd-kpi-variance');
                if (k) { k.textContent = (d.total_variance >= 0 ? '+' : '') + fmtCurrency(d.total_variance); k.classList.add('loaded'); }
                var vc = rootEl.querySelector('#sd-variance-card');
                if (vc) vc.style.setProperty('--kc', d.on_target ? 'var(--sd-emerald)' : 'var(--sd-rose)');
                k = rootEl.querySelector('#sd-kpi-variance-sub');
                if (k) k.textContent = (d.total_variance_pct >= 0 ? '+' : '') + (d.total_variance_pct || 0).toFixed(1) + '% vs pro-rated target';
                k = rootEl.querySelector('#sd-kpi-pending');
                if (k) { k.textContent = d.pending_invoices || 0; k.classList.add('loaded'); }
            }
        });

        frappe.call({
            method: API + 'get_sales_matrix',
            args: { territory: territory || null },
            callback: function (r) {
                if (!r.message) return;
                matrixCache = {
                    monthly: r.message.monthly,
                    weekly:  r.message.weekly,
                    daily:   r.message.daily,
                };
                renderMatrix('sd-matrix', matrixCache[currentMatrix]);
                if (arMatrixData) {
                    renderArMatrix('sd-ar-matrix', arMatrixData, arMatrixData.columns);
                }
            },
            error: function () {
                var el = rootEl.querySelector('#sd-matrix');
                if (el) el.innerHTML = '<p class="sd-empty">Error loading data.</p>';
            }
        });

        shimmerEl('sd-ar-matrix');
        frappe.call({
            method: API + 'get_ar_matrix',
            callback: function (r) {
                if (!r.message) return;
                arMatrixData = r.message;
                renderArMatrix('sd-ar-matrix', arMatrixData, arMatrixData.columns);
            },
            error: function () {
                var el = rootEl.querySelector('#sd-ar-matrix');
                if (el) el.innerHTML = '<p class="sd-empty">Error loading AR data.</p>';
            }
        });
    }

    function loadTerritories() {
        frappe.call({
            method: API + 'get_sales_territories',
            callback: function (r) {
                var sel = rootEl.querySelector('#sd-territory');
                if (!sel || !r.message || !r.message.length) return;
                r.message.forEach(function (t) {
                    var opt = document.createElement('option');
                    opt.value = opt.textContent = t.name;
                    sel.appendChild(opt);
                });
                sel.value = r.message[0].name;
                loadAll(currentPeriod);
            }
        });
    }

    // ── Event listeners ───────────────────────────────────────────
    rootEl.querySelectorAll('.sd-mtx-btn').forEach(function (btn) {
        btn.addEventListener('click', function () { setMatrixUI(btn.dataset.mtx); });
    });
    rootEl.querySelectorAll('.sd-view-btn').forEach(function (btn) {
        btn.addEventListener('click', function () { setViewUI(btn.dataset.view); });
    });
    rootEl.querySelectorAll('.sd-period-btn').forEach(function (btn) {
        btn.addEventListener('click', function () { currentPeriod = btn.dataset.period; loadAll(currentPeriod); });
    });
    var terrSel = rootEl.querySelector('#sd-territory');
    if (terrSel) terrSel.addEventListener('change', function () { loadAll(currentPeriod); });

    setMatrixUI(currentMatrix);
    setPeriodUI(currentPeriod);
    loadTerritories();
})();

/* ===== SALES DAILY SYNC — TOP SECTIONS JS ===== */
(function() {
  var API = "cannabis_management.api.sales_daily_sync.";

  function q(id) { return root_element.querySelector('#' + id); }
  function esc(s) {
    if (s === null || s === undefined) return '';
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function money(n) {
    n = parseFloat(n || 0);
    var neg = n < 0;
    var s = '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return neg ? '-' + s : s;
  }
  function fmtDate(d) {
    if (!d) return '—';
    var p = String(d).split(' ')[0].split('-');
    return p.length === 3 ? p[1] + '/' + p[2] + '/' + p[0] : d;
  }

  function loadCod() {
    frappe.call({
      method: API + 'get_cod_deliveries_last_7_days',
      callback: function(r) {
        if (!r || !r.message) return;
        var d = r.message;
        var dl = q('sds-cod-date'); if (dl) dl.textContent = fmtDate(d.from_date) + ' – ' + fmtDate(d.to_date);
        var tb = q('sds-cod-total');
        if (tb) tb.textContent = money(d.total) + ' · ' + d.count + ' order' + (d.count !== 1 ? 's' : '');
        var wrap = q('sds-cod-table'); if (!wrap) return;
        if (!d.rows.length) { wrap.innerHTML = '<div class="sds-empty">No COD orders shipped in the last 7 days.</div>'; return; }
        var h = '<table class="sds-tbl"><thead><tr><th>Order</th><th>Customer</th><th class="sds-r">Amount</th></tr></thead><tbody>';
        d.rows.forEach(function(row) {
          h += '<tr><td>'
             + '<a class="sds-link" href="/app/delivery-note/' + esc(row.delivery_note) + '" target="_blank">' + esc(row.delivery_note) + '</a>'
             + '<div class="sds-muted">' + fmtDate(row.date) + (row.sales_order ? ' · SO: ' + esc(row.sales_order) : '') + '</div>'
             + '</td><td>' + esc(row.customer) + '</td>'
             + '<td class="sds-r sds-mono">' + money(row.amount) + '</td></tr>';
        });
        h += '</tbody></table>';
        wrap.innerHTML = h;
      },
      error: function() { var w = q('sds-cod-table'); if (w) w.innerHTML = '<div class="sds-empty">Could not load.</div>'; }
    });
  }

  function loadPva() {
    frappe.call({
      method: API + 'get_predicted_vs_actual',
      callback: function(r) {
        if (!r || !r.message) return;
        var d = r.message;
        var e = q('sds-exp-total'); if (e) e.textContent = money(d.expected_total);
        var rc = q('sds-rcv-total'); if (rc) rc.textContent = money(d.received_total);
        var pd = q('sds-pva-date'); if (pd) pd.textContent = fmtDate(d.from_date) + ' – ' + fmtDate(d.to_date);
        var wrap = q('sds-pva-table'); if (!wrap) return;
        if (!d.rows.length) { wrap.innerHTML = '<div class="sds-empty">No outstanding invoices in the last 7 days.</div>'; return; }
        var h = '<table class="sds-tbl"><thead><tr><th>Reference</th><th class="sds-r">Expected</th><th class="sds-r">Received</th></tr></thead><tbody>';
        d.rows.forEach(function(row) {
          var full = row.expected > 0 && row.received >= row.expected;
          h += '<tr><td>'
             + '<a class="sds-link" href="/app/sales-invoice/' + esc(row.reference) + '" target="_blank">' + esc(row.reference) + '</a>'
             + '<div class="sds-muted">' + esc(row.customer) + ' · ' + fmtDate(row.date) + '</div>'
             + '</td>'
             + '<td class="sds-r sds-mono">' + money(row.expected) + '</td>'
             + '<td class="sds-r sds-mono ' + (full ? 'sds-pos' : 'sds-neg') + '">' + money(row.received) + '</td></tr>';
        });
        h += '</tbody></table>';
        wrap.innerHTML = h;
      },
      error: function() { var w = q('sds-pva-table'); if (w) w.innerHTML = '<div class="sds-empty">Could not load.</div>'; }
    });
  }

  loadCod();
  loadPva();
})();

/* ===== AR DASHBOARD SECTION JS ===== */
(function() {
  var SUMMARY_API   = "cannabis_management.api.sales_daily_sync.get_ar_week_summary";
  var COMPANIES_API = "cannabis_management.api.sales_daily_sync.get_ar_companies";
  var DEFAULT_COMPANY = "Motley Terpz";   // matches the AR Dashboard page default

  function q(id) { return root_element.querySelector('#' + id); }
  function money(n) {
    n = parseFloat(n || 0);
    var neg = n < 0;
    var s = '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return neg ? '-' + s : s;
  }
  function fmtDate(d) {
    if (!d) return '—';
    var p = String(d).split(' ')[0].split('-');
    return p.length === 3 ? p[1] + '/' + p[2] + '/' + p[0] : d;
  }
  function shimmer() {
    ['ars-legacy-bal','ars-legacy-coll','ars-new-acc','ars-paid'].forEach(function(id){
      var el = q(id); if (el) el.textContent = '…';
    });
  }

  function load(company) {
    shimmer();
    frappe.call({
      method: SUMMARY_API,
      args: { company: company },
      callback: function(r) {
        if (!r || !r.message) return;
        var d = r.message;
        var w = q('ars-week'); if (w) w.textContent = fmtDate(d.week_start) + ' – ' + fmtDate(d.week_end);
        var a = q('ars-legacy-bal'); if (a) a.textContent = money(d.legacy_ar_balance);
        var b = q('ars-legacy-coll'); if (b) b.textContent = money(d.legacy_collected_week);
        var c = q('ars-new-acc'); if (c) c.textContent = money(d.post_legacy_accumulated_week);
        var e = q('ars-paid'); if (e) e.textContent = money(d.ar_paid_down_week);
      }
    });
  }

  // Populate the company dropdown, then load the default company.
  frappe.call({
    method: COMPANIES_API,
    callback: function(r) {
      var sel = q('ars-company');
      var companies = (r && r.message) || [];
      if (sel) {
        companies.forEach(function(co) {
          var opt = document.createElement('option');
          opt.value = opt.textContent = co;
          sel.appendChild(opt);
        });
        var initial = companies.indexOf(DEFAULT_COMPANY) !== -1 ? DEFAULT_COMPANY : (companies[0] || '');
        sel.value = initial;
        sel.addEventListener('change', function() { load(this.value); });
        load(initial);
      } else {
        load(DEFAULT_COMPANY);
      }
    },
    error: function() { load(DEFAULT_COMPANY); }
  });
})();

/* ===== UNRECONCILED CUSTOMERS SECTION JS ===== */
(function() {
  var SUMMARY_API   = "cannabis_management.api.sales_daily_sync.get_unreconciled_customers";
  var COMPANIES_API = "cannabis_management.api.sales_daily_sync.get_ar_companies";
  var DEFAULT_COMPANY = "Motley Terpz";

  function q(id) { return root_element.querySelector('#' + id); }
  function esc(s) {
    if (s === null || s === undefined) return '';
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function money(n) {
    n = parseFloat(n || 0);
    var neg = n < 0;
    var s = '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return neg ? '-' + s : s;
  }
  function fmtDate(d) {
    if (!d) return '—';
    var p = String(d).split(' ')[0].split('-');
    return p.length === 3 ? p[1] + '/' + p[2] + '/' + p[0] : d;
  }

  function renderTrend(d) {
    var el = q('urc-trend'); if (!el) return;
    if (d.prev_count === null || d.prev_count === undefined) {
      el.className = 'urc-kpi-trend'; el.textContent = 'baseline set today · trend builds from tomorrow';
      return;
    }
    var diff = d.count - d.prev_count;
    var since = ' since ' + fmtDate(d.prev_date);
    if (diff < 0)      { el.className = 'urc-kpi-trend urc-trend-down'; el.textContent = '▼ ' + Math.abs(diff) + ' fewer' + since + ' (shrinking)'; }
    else if (diff > 0) { el.className = 'urc-kpi-trend urc-trend-up';   el.textContent = '▲ ' + diff + ' more' + since + ' — worth a conversation'; }
    else               { el.className = 'urc-kpi-trend urc-trend-flat'; el.textContent = 'No change' + since; }
    if (d.week_start_count !== null && d.week_start_count !== undefined) {
      var wd = d.count - d.week_start_count;
      el.textContent += ' · ' + (wd <= 0 ? '▼ ' + Math.abs(wd) : '▲ ' + wd) + ' vs start of week';
    }
  }

  function load(company) {
    var wrap = q('urc-table');
    if (wrap) wrap.innerHTML = '<div class="urc-loading"><div class="urc-spin"></div></div>';
