script:
(function(){
var root=root_element.querySelector('.dsync');if(!root)return;
var method='cannabis_management.api.daily_sync_dashboards.get_lab_daily_sync_dashboard';
function q(sel){return root.querySelector(sel)}
function qa(sel){return Array.prototype.slice.call(root.querySelectorAll(sel))}
function set(name,val){var els=root.querySelectorAll('[data-kpi="'+name+'"]');els.forEach(function(el){el.innerHTML=val;});}
function money(v){v=parseFloat(v||0);if(Math.abs(v)>=1000000)return '$'+(v/1000000).toFixed(1)+'M';if(Math.abs(v)>=1000)return '$'+(v/1000).toFixed(1)+'K';return '$'+v.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:0})}
function num(v,d){return parseFloat(v||0).toLocaleString(undefined,{maximumFractionDigits:d==null?0:d})}
function pct(v){return num(v,1)+'%'}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function fmtDate(d){if(!d)return'—';var p=String(d).split(' ')[0].split('-');return p.length===3?p[1]+'/'+p[2]+'/'+p[0]:d}

function delta(v,suffix,invertColor){
  v=parseFloat(v||0);
  var up=v>=0;
  var abs=Math.abs(v);
  // For yields: up is good (green). For COD/AR: up is bad (red). invertColor flips.
  var isGood=invertColor?(up):(!up);
  // Actually for lab yields: up = good = green
  var cls=up?(invertColor?'dsync-delta-dn':'dsync-delta-up'):(invertColor?'dsync-delta-up':'dsync-delta-dn');
  var arrow=up?'▲':'▼';
  return '<span class="dsync-delta '+cls+'">'+(up?arrow+' +':arrow+' -')+num(abs,2)+(suffix||'')+' vs prior day</span>';
}

function avg(rows,key){
  if(!rows||!rows.length)return 0;
  var s=0,c=0;
  rows.forEach(function(r){var v=parseFloat(r[key]||0);if(v>0){s+=v;c++;}});
  return c?s/c:0;
}

function lineChart(el,rows,key,color,opts){
  opts=opts||{};
  if(!el)return;
  rows=rows||[];key=key||'value';
  var vals=rows.map(function(r){return parseFloat(r[key]||0)});
  var max=Math.max.apply(null,vals.concat([0]));
  var min=Math.min.apply(null,vals.concat([0]));
  if(!rows.length||max===0){el.innerHTML='<div class="dsync-chart-empty">No data available for this period</div>';return;}
  var w=620,h=opts.small?120:150,p=24,span=Math.max(max-min,1);
  var pts=vals.map(function(v,i){
    var x=p+(i*(w-2*p)/Math.max(vals.length-1,1));
    var y=h-p-((v-min)/span*(h-2*p));
    return[x,y];
  });
  var d=pts.map(function(pt,i){return(i?'L':'M')+pt[0].toFixed(1)+' '+pt[1].toFixed(1)}).join(' ');
  var area=d+' L '+pts[pts.length-1][0]+' '+(h-p)+' L '+pts[0][0]+' '+(h-p)+' Z';
  // Benchmark line
  var benchLine='';
  if(opts.benchmark&&max>0){
    var by=h-p-((opts.benchmark-min)/span*(h-2*p));
    if(by>=p&&by<=(h-p)){
      benchLine='<line x1="'+p+'" y1="'+by.toFixed(1)+'" x2="'+(w-p)+'" y2="'+by.toFixed(1)+'" stroke="#fbbf24" stroke-width="1.5" stroke-dasharray="5,3" opacity=".7"><title>Benchmark: '+opts.benchmark+'</title></line>';
    }
  }
  var labels='';
  if(rows.length>=2){
    var positions=[0,Math.floor(rows.length/2),rows.length-1];
    positions.forEach(function(i){
      var pt=pts[i];
      var lbl=rows[i]?fmtDate(rows[i].date):'—';
      labels+='<text x="'+pt[0].toFixed(1)+'" y="'+(h-6)+'" text-anchor="middle" class="dsync-chart-lbl">'+esc(lbl)+'</text>';
    });
  }
  var lastPt=pts[pts.length-1];
  var lastVal=vals[vals.length-1];
  var tooltip=rows[rows.length-1]?fmtDate(rows[rows.length-1].date)+': '+num(lastVal,2):'—';
  var gid='cg'+Math.random().toString(36).substr(2,6);
  el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">'
    +'<defs><linearGradient id="'+gid+'" x1="0" y1="0" x2="0" y2="1">'
    +'<stop offset="0%" stop-color="'+color+'" stop-opacity="0.2"/>'
    +'<stop offset="100%" stop-color="'+color+'" stop-opacity="0.02"/>'
    +'</linearGradient></defs>'
    +'<path fill="url(#'+gid+')" d="'+area+'"></path>'
    +benchLine
    +'<path class="dsync-line" style="stroke:'+color+'" d="'+d+'"></path>'
    +'<circle cx="'+lastPt[0].toFixed(1)+'" cy="'+lastPt[1].toFixed(1)+'" r="4" fill="'+color+'" stroke="#fff" stroke-width="2"><title>'+esc(tooltip)+'</title></circle>'
    +'<line class="dsync-axis" x1="'+p+'" y1="'+(h-p+4)+'" x2="'+(w-p)+'" y2="'+(h-p+4)+'"></line>'
    +labels+'</svg>';
}

function barChart(el,rows,key,color){
  if(!el)return;
  rows=rows||[];key=key||'value';
  var vals=rows.map(function(r){return parseFloat(r[key]||0)});
  var max=Math.max.apply(null,vals.concat([0]));
  if(!rows.length||max===0){el.innerHTML='<div class="dsync-chart-empty">No data available for this period</div>';return;}
  var w=620,h=150,p=24,bw=(w-2*p)/vals.length*.7;
  var bars=vals.map(function(v,i){
    var x=p+i*(w-2*p)/vals.length+bw*.15;
    var bh=(v/max)*(h-2*p);
    var yt=rows[i]?fmtDate(rows[i].date)+'\n'+num(v,1)+' lbs':'';
    return '<rect fill="'+color+'" x="'+x.toFixed(1)+'" y="'+(h-p-bh).toFixed(1)+'" width="'+bw.toFixed(1)+'" height="'+bh.toFixed(1)+'" rx="3" opacity=".78"><title>'+esc(yt)+'</title></rect>';
  }).join('');
  var labels='';
  var positions=[0,Math.floor(rows.length/2),rows.length-1];
  positions.forEach(function(i){
    if(!rows[i])return;
    var x=p+i*(w-2*p)/vals.length+bw*.15+bw/2;
    labels+='<text x="'+x.toFixed(1)+'" y="'+(h-6)+'" text-anchor="middle" class="dsync-chart-lbl">'+esc(fmtDate(rows[i].date))+'</text>';
  });
  el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">'+bars+'<line class="dsync-axis" x1="'+p+'" y1="'+(h-p+4)+'" x2="'+(w-p)+'" y2="'+(h-p+4)+'"></line>'+labels+'</svg>';
}

function table(headers,rows){
  if(!rows||!rows.length)return '<div class="dsync-empty">No data found for this period.</div>';
  return '<table><thead><tr>'+headers.map(function(h){return'<th>'+esc(h.label)+'</th>'}).join('')+'</tr></thead>'
    +'<tbody>'+rows.map(function(r){return'<tr>'+headers.map(function(h){return'<td>'+h.f(r)+'</td>'}).join('')+'</tr>'}).join('')+'</tbody></table>';
}

function renderLab(d){
  var p=d.production||{};
  // Yesterday date
  var ydEl=q('#dsync-yesterday-date');
  if(ydEl)ydEl.textContent=d.yesterday?fmtDate(d.yesterday):'';
  // Date ranges
  var start=d.yesterday?(function(){var dt=new Date(d.yesterday);dt.setDate(dt.getDate()-29);return dt.toISOString().slice(0,10);})():'—';
  var dr=start?fmtDate(start)+' – '+fmtDate(d.yesterday):'Last 30 days';
  set('lab_date_range',dr);set('lab_date_range2',dr);set('lab_date_range3',dr);set('lab_date_range4',dr);
  // KPIs
  var lbs=parseFloat(p.lbs_ran||0);
  var lbsCls=lbs>=700?'dsync-pct-green':lbs>=400?'dsync-pct-amber':'dsync-pct-red';
  set('lbs','<span class="dsync-big-num '+lbsCls+'">'+num(lbs,1)+' <span style="font-size:14px;font-weight:600;">lbs</span></span>');
  set('lbs_delta',delta(parseFloat(p.lbs_delta||0),' lbs',true));
  var lb=q('[data-bar="lbs"]');if(lb)lb.style.width=Math.min(lbs/900*100,100)+'%';
  var hash=parseFloat(p.hash_yield_pct||0);
  var hashCls=hash>=20?'dsync-pct-green':hash>=12?'dsync-pct-amber':'dsync-pct-red';
  set('hash_yield','<span class="dsync-big-num '+hashCls+'">'+pct(hash)+'</span>');
  set('hash_delta',delta(parseFloat(p.hash_yield_delta||0),'%',true));
  var hb=q('[data-bar="hash"]');if(hb)hb.style.width=Math.min(hash/20*100,100)+'%';
  var rosin=parseFloat(p.rosin_yield_pct||0);
  var rosinCls=rosin>=70?'dsync-pct-green':rosin>=50?'dsync-pct-amber':'dsync-pct-red';
  set('rosin_yield','<span class="dsync-big-num '+rosinCls+'">'+pct(rosin)+'</span>');
  set('rosin_delta',delta(parseFloat(p.rosin_yield_delta||0),'%',true));
  var rb=q('[data-bar="rosin"]');if(rb)rb.style.width=Math.min(rosin/70*100,100)+'%';
  // Trends
  var trends=d.trends||[];
  lineChart(q('[data-chart="hash"]'),trends,'hash_yield_pct','#d97706',{benchmark:20});
  lineChart(q('[data-chart="rosin"]'),trends,'rosin_yield_pct','#059669',{benchmark:70});
  barChart(q('[data-chart="lbs"]'),trends,'lbs_ran','#401090');
  // Avg badges
  var ha=q('#dsync-hash-avg');if(ha)ha.textContent='Avg: '+pct(avg(trends,'hash_yield_pct'));
  var ra=q('#dsync-rosin-avg');if(ra)ra.textContent='Avg: '+pct(avg(trends,'rosin_yield_pct'));
  var la=q('#dsync-lbs-avg');if(la)la.textContent='Avg: '+num(avg(trends,'lbs_ran'),1)+' lbs';
  // Pending invoices
  var pi=d.pending_invoices||{};
  set('pending_invoices','<span class="dsync-big-num" style="color:#7c3aed">'+num(pi.count)+'</span>');
  lineChart(q('[data-chart="pending"]'),(pi.trend||[]),'value','#7c3aed',{small:true});
  // Discrepancies
  var disc=d.discrepancies||{};
  var cnt=disc.open_count||0;
  var discBadge=q('#dsync-disc-badge');
  if(discBadge){discBadge.textContent=cnt+' open';discBadge.className='dsync-disc-badge '+(cnt>0?'dsync-disc-badge-warn':'dsync-disc-badge-ok');}
  set('disc_alert',cnt+' open discrepancies'+(disc.doctype?' — from '+esc(disc.doctype):' — reconciliation DocType not found'));
  var discEl=q('[data-table="disc"]');
  if(discEl)discEl.innerHTML=table([
    {label:'Item',f:function(r){return'<span class="dsync-cust">'+esc(r.item)+'</span>'}},
    {label:'Status',f:function(r){
      var cls=r.status&&r.status.toLowerCase().indexOf('open')!==-1?'dsync-badge-red':'dsync-badge-amber';
      return'<span class="dsync-badge-days '+cls+'">'+esc(r.status)+'</span>';
    }}
  ],disc.rows);
  // EOD
  var eodEl=q('[data-table="eod"]');
  var eodRows=d.eod_rows||[];
  var eb=q('#dsync-eod-count');if(eb)eb.textContent=eodRows.length+' runs';
  if(eodEl)eodEl.innerHTML=table([
    {label:'Run',f:function(r){return'<span class="dsync-cust">'+esc(r.run)+'</span>'}},
    {label:'Operator',f:function(r){return esc(r.operator||'—')}},
    {label:'Input (lbs)',f:function(r){return'<span class="dsync-money">'+num(r.input_lbs,1)+'</span>'}},
    {label:'Hash %',f:function(r){
      var v=parseFloat(r.hash_pct||0);
      var cls=v>=20?'dsync-pct-green':v>=12?'dsync-pct-amber':'dsync-pct-red';
      return'<span class="'+cls+'" style="font-weight:700">'+pct(v)+'</span>';
    }},
    {label:'Note',f:function(r){return'<span style="color:#94a3b8;font-size:11px">'+esc(r.issue||'—')+'</span>'}}
  ],eodRows);
  // Shipments
  var shipData=d.shipments||{};
  var shipRows=shipData.rows||[];
  var sc=q('#dsync-ship-count');if(sc)sc.textContent=shipRows.length+' shipments';
  var sa=q('#dsync-ship-avg');if(sa)sa.textContent='Avg: '+num(avg(shipData.trend||[],'value'),1)+'/day';
  var shipEl=q('[data-table="shipments"]');
  if(shipEl)shipEl.innerHTML=table([
    {label:'DN #',f:function(r){return'<a class="dsync-link" href="/app/delivery-note/'+esc(r.name)+'" target="_blank">'+esc(r.name)+'</a>'}},
    {label:'Customer',f:function(r){return'<span class="dsync-cust">'+esc(r.customer)+'</span>'}},
    {label:'Items',f:function(r){return num(r.items)}},
    {label:'Qty (lbs)',f:function(r){return'<span class="dsync-money">'+num(r.qty,1)+'</span>'}},
    {label:'Value',f:function(r){return'<span class="dsync-money">'+money(r.value)+'</span>'}}
  ],shipRows);
  barChart(q('[data-chart="shipments"]'),shipData.trend||[],'value','#401090');
}

function load(){
  qa('[data-kpi]').forEach(function(el){
    if(!el.innerHTML||el.innerHTML==='—'||el.innerHTML.indexOf('dsync-shimmer')!==-1){
      el.innerHTML='<span class="dsync-shimmer"></span>';
    }
  });
  frappe.call({
    method:method,
    callback:function(r){var d=r.message||{};renderLab(d);set('last_refresh',new Date().toLocaleTimeString());},
    error:function(){frappe.msgprint('Unable to load Lab Daily Sync data.');}
  });
}

var btn=q('[data-action="refresh"]');
if(btn)btn.addEventListener('click',load);
load();
setInterval(load,30*60*1000);
})();

style:
.dsync{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:1600px;margin:0 auto;padding:24px;color:#1e293b}.dsync *{box-sizing:border-box}

/* ── Header ── */
.dsync-header{background:linear-gradient(135deg,#401090 0%,#7c3aed 60%,#C060E0 100%);color:#fff;border-radius:12px;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;gap:16px}
.dsync-header-left{display:flex;align-items:center;gap:16px}
.dsync-header-right{display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.dsync-last-refresh{font-size:11px;color:rgba(255,255,255,.7);font-family:Consolas,'Courier New',monospace}
.dsync-header h2{font-size:20px;margin:0 0 2px;font-weight:800;letter-spacing:-.3px;color:#fff;}
.dsync-header p{margin:0;font-size:11.5px;opacity:.82}
.dsync-eyebrow{font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;opacity:.75;margin-bottom:3px}
.dsync-logo{width:48px;height:48px;border-radius:10px;border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.15);display:flex;align-items:center;justify-content:center;font-weight:900;font-size:16px;flex-shrink:0}
.dsync-refresh{display:inline-flex;align-items:center;gap:6px;border:1px solid rgba(255,255,255,.4);background:rgba(255,255,255,.15);color:#fff;border-radius:8px;padding:8px 14px;font-size:12px;font-weight:700;cursor:pointer;transition:background .15s}
.dsync-refresh:hover{background:rgba(255,255,255,.25)}

/* ── Alert ── */
.dsync-alert{border-radius:8px;padding:10px 14px;font-size:12px;font-weight:600;margin-bottom:20px;display:flex;align-items:center;gap:8px}
.dsync-info{background:#eff6ff;border:1px solid #bfdbfe;color:#1d4ed8}
.dsync-warn{background:#fff7ed;border:1px solid #fed7aa;color:#9a3412}
.dsync-danger{background:#fff1f2;border:1px solid #fecdd3;color:#9f1239}

/* ── Section headers ── */
.dsync-section{font-size:11px;font-weight:800;color:#401090;border-bottom:2px solid #e2e8f0;margin:28px 0 14px;padding-bottom:8px;text-transform:uppercase;letter-spacing:1px;display:flex;align-items:center;gap:7px}
.dsync-section-icon{display:inline-flex;align-items:center;opacity:.7}

/* ── Grid ── */
.dsync-grid{display:grid;gap:14px}
.dsync-grid-4{grid-template-columns:repeat(4,1fr)}
.dsync-grid-3{grid-template-columns:repeat(3,1fr)}
.dsync-grid-2{grid-template-columns:repeat(2,1fr)}

/* ── KPI Cards ── */
.dsync-kpi-card{position:relative;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px 18px 14px;overflow:hidden;transition:all .2s}
.dsync-kpi-card:hover{border-color:#c7d2fe;transform:translateY(-2px);box-shadow:0 4px 16px rgba(0,0,0,.06)}
.dsync-kpi-accent{position:absolute;top:0;left:0;right:0;height:3px;background:var(--ka)}
.dsync-kpi-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:4px}
.dsync-kpi-label{font-size:12px;font-weight:700;color:#475569;margin-bottom:8px}
.dsync-kpi-value{min-height:36px;margin-bottom:4px}
.dsync-big-num{font-size:28px;font-weight:900;line-height:1;color:var(--ka,#401090);display:block}
.dsync-kpi-delta{min-height:18px;margin-bottom:10px}
.dsync-shimmer{display:inline-block;width:80px;height:28px;border-radius:6px;background:linear-gradient(110deg,#f1f5f9 25%,#e2e8f0 50%,#f1f5f9 75%);background-size:200% 100%;animation:dsShimmer 1.4s ease-in-out infinite}
.dsync-shimmer-sm{width:50px;height:22px}
.dsync-source-tag{display:inline-block;font-size:9.5px;font-weight:600;letter-spacing:.3px;background:#f1f5f9;color:#64748b;padding:2px 8px;border-radius:20px;font-family:Consolas,'Courier New',monospace}

/* ── Delta ── */
.dsync-delta{font-size:11px;font-weight:700}
.dsync-delta-up{color:#059669}
.dsync-delta-dn{color:#dc2626}

/* ── Pct colors ── */
.dsync-pct-green{color:#059669 !important}
.dsync-pct-amber{color:#d97706 !important}
.dsync-pct-red{color:#dc2626 !important}

/* ── Progress meters ── */
.dsync-meter-wrap{margin-bottom:10px}
.dsync-meter{height:6px;background:#f1f5f9;border-radius:4px;overflow:hidden;margin-bottom:4px}
.dsync-meter span{display:block;height:100%;background:linear-gradient(90deg,#401090,#C060E0);width:0;transition:width .6s cubic-bezier(.4,0,.2,1);border-radius:4px}
.dsync-meter-amber span{background:linear-gradient(90deg,#d97706,#fbbf24)}
.dsync-meter-green span{background:linear-gradient(90deg,#059669,#34d399)}
.dsync-meter-label{font-size:10px;color:#94a3b8}

/* ── Mini KPI card (inline) ── */
.dsync-kpi-card-mini{display:flex;flex-direction:column;align-items:center;text-align:center;gap:2px;flex-shrink:0}
.dsync-mini-label{font-size:10px;color:#94a3b8;font-weight:600;text-transform:uppercase;letter-spacing:.5px}

/* ── Panels ── */
.dsync-panel{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px;box-shadow:0 1px 3px rgba(0,0,0,.04)}
.dsync-panel-header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:12px}
.dsync-panel-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:3px}
.dsync-panel-title{font-size:13px;font-weight:700;color:#1e293b}
.dsync-panel-badge{background:#f1f5f9;color:#475569;border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;white-space:nowrap;flex-shrink:0;font-family:Consolas,'Courier New',monospace}

/* ── Charts ── */
.dsync-chart{height:160px;margin:4px 0 0}
.dsync-chart-sm{height:100px}
.dsync-chart svg{width:100%;height:100%;overflow:visible}
.dsync-axis{stroke:#e5e7eb;stroke-width:1}
.dsync-line{fill:none;stroke-width:2.5;stroke-linecap:round}
.dsync-chart-lbl{fill:#94a3b8;font-size:9.5px;font-family:-apple-system,sans-serif}
.dsync-chart-empty{height:100%;display:flex;align-items:center;justify-content:center;color:#94a3b8;font-size:12px;background:#fafafa;border-radius:8px}
.dsync-chart-footer{display:flex;align-items:center;justify-content:space-between;margin-top:8px;flex-wrap:wrap;gap:4px}
.dsync-chart-footer span{font-size:11px;color:#94a3b8}

/* ── Tables ── */
.dsync-table-card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden}
.dsync-table-head{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #f1f5f9;background:#fafbfc}
.dsync-table-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:2px}
.dsync-table-title{font-size:13px;font-weight:700;color:#1e293b}
.dsync-table-badge{background:#f1f5f9;color:#475569;border-radius:20px;padding:4px 10px;font-size:11px;font-weight:700;white-space:nowrap}
.dsync-disc-badge{border-radius:20px;padding:4px 10px;font-size:11px;font-weight:700;white-space:nowrap}
.dsync-disc-badge-warn{background:#fff1f2;color:#dc2626}
.dsync-disc-badge-ok{background:#f0fdf4;color:#059669}
.dsync-table-footer{padding:10px 18px;border-top:1px solid #f1f5f9;font-size:10px;color:#94a3b8;font-family:Consolas,'Courier New',monospace}
.dsync table{width:100%;border-collapse:collapse}
.dsync th{background:#f8fafc;color:#475569;padding:9px 14px;font-size:10px;text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid #e2e8f0;white-space:nowrap}
.dsync td{padding:10px 14px;border-bottom:1px solid #f8fafc;font-size:12.5px;color:#334155}
.dsync th:not(:first-child),.dsync td:not(:first-child){text-align:right}
.dsync tr:last-child td{border-bottom:none}
.dsync tbody tr:hover td{background:#fafbff}
.dsync-empty{padding:28px;text-align:center;color:#94a3b8;font-size:12px}
.dsync-tbl-loading{padding:28px;text-align:center}
.dsync-spin{display:inline-block;width:20px;height:20px;border:3px solid #e2e8f0;border-top-color:#401090;border-radius:50%;animation:dsSpin .7s linear infinite}
.dsync-cust{font-weight:600;color:#1e293b}
.dsync-money{font-family:Consolas,'Courier New',monospace;font-weight:700;color:#1e293b}
.dsync-link{color:#401090;font-weight:700;font-family:Consolas,'Courier New',monospace;font-size:12px;text-decoration:none}
.dsync-link:hover{text-decoration:underline}
.dsync-badge-days{border-radius:20px;padding:2px 8px;font-size:10.5px;font-weight:700}
.dsync-badge-ok{background:#f0fdf4;color:#059669}
.dsync-badge-amber{background:#fffbeb;color:#d97706}
.dsync-badge-red{background:#fff1f2;color:#dc2626}

/* ── Footer ── */
.dsync-footer{display:flex;align-items:center;justify-content:space-between;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px 18px;margin-top:24px;font-size:11px;color:#64748b;flex-wrap:wrap;gap:8px}

/* ── Animations ── */
@keyframes dsShimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}
@keyframes dsSpin{to{transform:rotate(360deg)}}

@media(max-width:1200px){.dsync-grid-3{grid-template-columns:repeat(2,1fr)}}
@media(max-width:900px){.dsync-grid-4,.dsync-grid-2{grid-template-columns:1fr}}
@media(max-width:768px){.dsync{padding:12px}.dsync-header{flex-direction:column;align-items:flex-start}.dsync-grid-3{grid-template-columns:1fr}}

script:
/* =================== DISTRIBUTION HUB JS =================== */
/* Calls the whitelisted methods in cannabis_management/api/distribution_hub.py
   to fill in the pipeline, manifests, storage gauge, bins and shortcuts.
   No data is hardcoded here.

   NOTE: Frappe renders this Custom HTML Block inside a Shadow DOM
   (frappe.create_shadow_element) and injects `root_element` (the shadow
   root) into this script's scope. Elements must be queried through
   root_element, NOT the global `document` -- document.getElementById
   cannot see across the shadow boundary. */

(function () {
  "use strict";

  const API_MODULE = "cannabis_management.api.distribution_hub";
  let currentCompany = "";

  function byId(id) {
    return root_element.getElementById(id);
  }

  function docLink(doctype, name) {
    if (!name) return "--";
    const slug = doctype.toLowerCase().replace(/ /g, "-");
    const href = `/app/${slug}/${encodeURIComponent(name)}`;
    return `<a href="${href}" class="dh-link" data-doctype="${escapeHtml(doctype)}" data-name="${escapeHtml(name)}">${escapeHtml(name)}</a>`;
  }

  /* ---------- Generic API wrapper ---------- */
  function callApi(method, args) {
    args = args || {};
    if (window.frappe && frappe.call) {
      return frappe.call({
        method: `${API_MODULE}.${method}`,
        args: args
      }).then((r) => r.message);
    }
    const params = new URLSearchParams(args).toString();
    return fetch(`/api/method/${API_MODULE}.${method}?${params}`, {
      headers: { "X-Frappe-CSRF-Token": window.csrf_token || "" }
    })
      .then((res) => res.json())
      .then((data) => data.message);
  }

  /* ---------- Renderers ---------- */

  function populateCompanyFilter(meta) {
    const sel = byId("dh-company-filter");
    if (!sel) return;
    const selected = sel.value;
    sel.innerHTML = `<option value="">All Companies</option>`;
    (meta.companies || []).forEach((c) => {
      const opt = document.createElement("option");
      opt.value = c;
      opt.textContent = c;
      sel.appendChild(opt);
    });
    sel.value = selected;
  }

  function renderStagePipeline(data) {
    const bar = byId("dh-stage-bar");
    bar.innerHTML = "";
    (data.stages || []).forEach((stage, idx) => {
      const col = document.createElement("div");
      col.className = `stage-col stage-${idx + 1}`;
      col.innerHTML = `
        <div class="stg-lbl">${escapeHtml(stage.label)}</div>
        <div class="stg-count">${stage.count}</div>
      `;
      bar.appendChild(col);
    });

    const tbody = byId("dh-order-tbody");
    tbody.innerHTML = "";
    if (!data.orders || !data.orders.length) {
      tbody.innerHTML = `<tr><td colspan="7" class="dh-loading-row">No orders found.</td></tr>`;
      return;
    }
    data.orders.forEach((o) => {
      const tr = document.createElement("tr");
      tr.innerHTML = `
        <td>${docLink("Sales Order", o.name)}</td>
        <td>${docLink("Customer", o.customer)}</td>
        <td>${escapeHtml(o.bill_to || "Same")}</td>
        <td>${escapeHtml(o.pickup_dropoff || "--")}</td>
        <td>${escapeHtml(o.requested || "--")}</td>
        <td>${statusPill(o.stage, stageClass(o.stage))}</td>
        <td>${escapeHtml(o.notes || "--")}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  function renderManifests(rows) {
    const tbody = byId("dh-manifest-tbody");
    tbody.innerHTML = "";
    if (!rows || !rows.length) {
      tbody.innerHTML = `<tr><td colspan="7" class="dh-loading-row">No manifests found.</td></tr>`;
      return;
    }
    rows.forEach((m) => {
      const tr = document.createElement("tr");
      tr.innerHTML = `
        <td>${escapeHtml(m.manifest_no)}</td>
        <td>${docLink("Delivery Note", m.dn_ref)}</td>
        <td>${docLink("Customer", m.customer)}</td>
        <td>${m.items_count}</td>
        <td>${escapeHtml(m.weight)}</td>
        <td>${escapeHtml(m.shipment_ref)}</td>
        <td>${statusPill(m.status, manifestClass(m.status))}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  function renderGauge(gauge) {
    const pct = Math.max(0, Math.min(100, gauge.percent || 0));
    byId("dh-gauge-pct").textContent = `${pct}%`;

    const angle = Math.PI * (1 - pct / 100);
    const cx = 100, cy = 110, r = 80;
    const x = cx - r * Math.cos(angle);
    const y = cy - r * Math.sin(angle);
    const largeArc = pct > 50 ? 1 : 0;
    const arcPath = `M 20 110 A 80 80 0 ${largeArc} 1 ${x.toFixed(1)} ${y.toFixed(1)}`;
    const arc = byId("dh-gauge-arc");
    arc.setAttribute("d", arcPath);

    let color = "var(--ok)";
    if (pct >= 90) color = "var(--bad)";
    else if (pct >= 70) color = "var(--warn)";
    arc.setAttribute("stroke", color);
  }

  function renderBins(bins) {
    const list = byId("dh-bin-list");
    list.innerHTML = "";
    (bins || []).forEach((b) => {
      const li = document.createElement("li");
      li.className = "qitem";
      let color = "";
      const hasPct = b.percent !== null && b.percent !== undefined;
      if (hasPct && b.percent >= 90) color = "color:var(--bad)";
      else if (hasPct && b.percent >= 70) color = "color:var(--warn)";
      li.innerHTML = `
        <div>
          <div class="qname">${escapeHtml(b.warehouse)}</div>
          <div class="qmeta">${escapeHtml(b.capacity_label)}</div>
        </div>
        <span class="qval" style="${color}">${hasPct ? b.percent + "%" : "--"}</span>
      `;
      list.appendChild(li);
    });
  }

  function renderShortcuts(items) {
    const grid = byId("dh-shortcuts-grid");
    grid.innerHTML = "";
    (items || []).forEach((s) => {
      const div = document.createElement("div");
      div.className = `shortcut ${s.kind}`;
      div.innerHTML = `
        <div class="ic">${escapeHtml(s.icon)}</div>
        <span class="lbl">${escapeHtml(s.label)}</span>
        <span class="sub">${escapeHtml(s.sub)}</span>
        ${s.is_new ? '<span class="newf">NEW</span>' : ""}
      `;
      div.addEventListener("click", () => handleShortcutClick(s));
      grid.appendChild(div);
    });
  }

  function handleShortcutClick(shortcut) {
    if (shortcut.route && window.frappe) {
      frappe.set_route(shortcut.route);
    } else if (shortcut.url) {
      window.location.href = shortcut.url;
    }
  }

  /* ---------- Helpers ---------- */
  function statusPill(label, cls) {
    return `<span class="status-pill ${cls}">${escapeHtml(label)}</span>`;
  }
  function stageClass(stage) {
    const map = {
      "Not Set": "info",
      "Need to Schedule": "warn",
      "Scheduled": "info",
      "Order Preparing": "info",
      "Order Prepared": "info",
      "Order Staged": "pur",
      "Order Closed Out": "ok"
    };
    return map[stage] || "info";
  }
  function manifestClass(status) {
    const map = { "Draft": "warn", "To Bill": "info", "Completed": "ok", "Cancelled": "bad" };
    return map[status] || "info";
  }
  function escapeHtml(str) {
    if (str === null || str === undefined) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }

  /* ---------- Data loaders ---------- */
  function loadAll() {
    callApi("get_meta").then(populateCompanyFilter).catch(console.error);
    callApi("get_pipeline", { company: currentCompany }).then(renderStagePipeline).catch(console.error);
    callApi("get_manifests", { company: currentCompany }).then(renderManifests).catch(console.error);
    callApi("get_storage_gauge").then(renderGauge).catch(console.error);
    callApi("get_bin_utilization").then(renderBins).catch(console.error);
    callApi("get_shortcuts").then(renderShortcuts).catch(console.error);
  }

  /* ---------- Init ---------- */
  function init() {
    const companySelect = byId("dh-company-filter");
    if (!companySelect) return; // block markup not ready yet

    root_element.addEventListener("click", (e) => {
      const link = e.target.closest(".dh-link");
      if (link && window.frappe) {
        e.preventDefault();
        frappe.set_route("Form", link.dataset.doctype, link.dataset.name);
      }
    });

    companySelect.addEventListener("change", (e) => {
      currentCompany = e.target.value;
      callApi("get_pipeline", { company: currentCompany }).then(renderStagePipeline).catch(console.error);
      callApi("get_manifests", { company: currentCompany }).then(renderManifests).catch(console.error);
    });

    loadAll();

    setInterval(loadAll, 30000);
  }

  init();

  window.DistributionHub = { init, loadAll };
})();

style:
/* =================== DISTRIBUTION HUB CSS =================== */
/* Agar aapke ERP theme me already yeh CSS vars defined hain (ERPNext/Frappe desk theme
   ya kisi bhi design system se) to unko override na karein — yeh file unko use karti hai.
   Agar vars defined nahi hain to neeche wale :root fallback defaults use ho jayenge. */

.dist-hub {
  --brand-purple: #6c4fc9;
  --brand-lavender: #a78bfa;
  --line: #e5e2f0;
  --muted: #8a8599;
  --ok: #22c55e;
  --warn: #f59e0b;
  --bad: #ef4444;
  --info: #3b82f6;
  --pur: #8b5cf6;
  --bg-card: #ffffff;
  --bg-page: #f7f6fb;
  --text: #1f1b2e;

  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--text);
  background: var(--bg-page);
  padding: 20px;
  border-radius: 8px;
}

.dist-hub * { box-sizing: border-box; }

/* ---- Badge (used in section titles) ---- */
.dist-hub .badge {
  background: var(--brand-lavender);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  text-transform: uppercase;
}

/* ---- Body layout (sidebar/header removed — single-column main content) ---- */
.dist-hub .ws-body { display: flex; align-items: flex-start; }
.dist-hub .ws-main { flex: 1; display: flex; flex-direction: column; gap: 18px; min-width: 0; }

/* ---- Section card ---- */
.dist-hub .sec {
  background: var(--bg-card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 16px;
}
.dist-hub .sec-title { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; flex-wrap: wrap; }
.dist-hub .sec-title .t { font-size: 14px; font-weight: 700; }
.dist-hub .dh-select {
  margin-left: auto;
  font-size: 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 4px 8px;
  background: var(--bg-page);
}

/* ---- Stage bar (pipeline) ---- */
.dist-hub .stage-bar { display: flex; gap: 6px; margin-bottom: 14px; flex-wrap: wrap; }
.dist-hub .stage-col {
  flex: 1;
  min-width: 90px;
  background: var(--bg-page);
  border-radius: 8px;
  padding: 10px 8px;
  text-align: center;
  border-top: 3px solid var(--brand-lavender);
}
.dist-hub .stg-lbl { font-size: 10.5px; color: var(--muted); margin-bottom: 4px; min-height: 26px; }
.dist-hub .stg-count { font-size: 20px; font-weight: 800; color: var(--brand-purple); }
.dist-hub .stage-loading, .dh-loading-row { color: var(--muted); font-size: 12px; font-style: italic; }

/* stage color accents (1-7) */
.dist-hub .stage-1 { border-top-color: #94a3b8; }
.dist-hub .stage-2 { border-top-color: var(--warn); }
.dist-hub .stage-3 { border-top-color: var(--info); }
.dist-hub .stage-4 { border-top-color: var(--pur); }
.dist-hub .stage-5 { border-top-color: #06b6d4; }
.dist-hub .stage-6 { border-top-color: var(--brand-lavender); }
.dist-hub .stage-7 { border-top-color: var(--ok); }

/* ---- Table ---- */
.dist-hub .tbl { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.dist-hub .tbl th {
  text-align: left;
  font-size: 10.5px;
  text-transform: uppercase;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
  padding: 8px 6px;
}
.dist-hub .tbl td { padding: 8px 6px; border-bottom: 1px solid var(--line); }
.dist-hub .tbl tr:hover td { background: var(--bg-page); }

.dist-hub .dh-link { color: var(--brand-purple); font-weight: 600; text-decoration: none; }
.dist-hub .dh-link:hover { text-decoration: underline; }

.dist-hub .status-pill {
  font-size: 10.5px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  display: inline-block;
}
.dist-hub .status-pill.info { background: #dbeafe; color: #1d4ed8; }
.dist-hub .status-pill.warn { background: #fef3c7; color: #b45309; }
.dist-hub .status-pill.ok { background: #dcfce7; color: #15803d; }
.dist-hub .status-pill.pur { background: #ede9fe; color: #6d28d9; }
.dist-hub .status-pill.bad { background: #fee2e2; color: #b91c1c; }

/* ---- Chart row (gauge + bins) ---- */
.dist-hub .chart-row.eq { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.dist-hub .legend { display: flex; gap: 14px; font-size: 10.5px; color: var(--muted); margin-top: 8px; }
.dist-hub .legend .sw { width: 8px; height: 8px; border-radius: 2px; display: inline-block; margin-right: 4px; }
.dist-hub .cap { font-size: 11px; color: var(--muted); }

/* ---- Bin list ---- */
.dist-hub .qlist { list-style: none; margin: 0; padding: 0; }
.dist-hub .qitem {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
}
.dist-hub .qitem:last-child { border-bottom: none; }
.dist-hub .qname { font-size: 13px; font-weight: 600; }
.dist-hub .qmeta { font-size: 11px; color: var(--muted); }
.dist-hub .qval { font-weight: 700; font-size: 13px; }

/* ---- Shortcuts grid ---- */
.dist-hub .shortcuts { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 10px; }
.dist-hub .shortcut {
  background: var(--bg-page);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  cursor: pointer;
  position: relative;
  transition: transform .12s ease, box-shadow .12s ease;
}
.dist-hub .shortcut:hover { transform: translateY(-2px); box-shadow: 0 4px 10px rgba(0,0,0,.06); }
.dist-hub .shortcut .ic {
  width: 26px; height: 26px;
  border-radius: 6px;
  background: var(--brand-lavender);
  color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 800;
}
.dist-hub .shortcut .lbl { font-size: 12px; font-weight: 700; }
.dist-hub .shortcut .sub { font-size: 10.5px; color: var(--muted); }
.dist-hub .shortcut .newf {
  position: absolute; top: 8px; right: 8px;
  font-size: 8.5px; font-weight: 800; color: #fff;
  background: var(--ok); padding: 1px 5px; border-radius: 4px;
}

/* ---- Responsive ---- */
@media (max-width: 900px) {
  .dist-hub .ws-body { flex-direction: column; }
  .dist-hub .ws-sidebar { width: 100%; position: static; }
  .dist-hub .chart-row.eq { grid-template-columns: 1fr; }
}

script:
/* ===== COMPANY RECORDS HUB ===== */
(function () {
	const open_card = (el) => {
		if (el.dataset.doctype) {
			frappe.set_route("List", el.dataset.doctype);
		} else if (el.dataset.report) {
			frappe.set_route("query-report", el.dataset.report);
		}
	};

	root_element.querySelectorAll(".crh-card").forEach((el) => {
		el.addEventListener("click", () => open_card(el));
		el.addEventListener("keydown", (e) => {
			if (e.key === "Enter" || e.key === " ") {
				e.preventDefault();
				open_card(el);
			}
		});
	});

	// live document counts + hero total
	const total_el = root_element.querySelector(".crh-total");
	let total = 0;
	const doctype_cards = [...root_element.querySelectorAll(".crh-card[data-doctype]")];
	Promise.all(
		doctype_cards.map((el) =>
			frappe
				.xcall("frappe.client.get_count", { doctype: el.dataset.doctype })
				.then((n) => {
					el.querySelector(".crh-count").textContent = n || 0;
					total += n || 0;
				})
				.catch(() => {
					el.querySelector(".crh-count").textContent = "–";
				})
		)
	).then(() => {
		if (total_el) total_el.textContent = total;
	});
})();

style:
.crh { font-family: "InterVariable", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  max-width: 1400px; margin: 0 auto; padding: 4px 2px 24px; color: var(--text-color, #1f2937); }
.crh * { box-sizing: border-box; }

/* ---- hero ---- */
.crh-hero { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 24px;
  flex-wrap: wrap; border-radius: 18px; padding: 28px 32px; margin-bottom: 28px; overflow: hidden; color: #fff;
  background: linear-gradient(135deg, #064e3b 0%, #065f46 45%, #0f766e 100%); }
.crh-hero::before, .crh-hero::after { content: ""; position: absolute; border-radius: 50%;
  background: rgba(255,255,255,.07); pointer-events: none; }
.crh-hero::before { width: 300px; height: 300px; right: -80px; top: -140px; }
.crh-hero::after { width: 180px; height: 180px; right: 140px; bottom: -110px; background: rgba(255,255,255,.05); }
.crh-hero h1 { margin: 0 0 6px; font-size: 1.45rem; font-weight: 700; letter-spacing: -.02em; color: #fff; }
.crh-hero p { margin: 0; max-width: 640px; font-size: .85rem; line-height: 1.55; color: rgba(255,255,255,.82); }
.crh-hero-chip { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 14px 26px; border-radius: 14px; background: rgba(255,255,255,.12); backdrop-filter: blur(6px);
  border: 1px solid rgba(255,255,255,.18); }
.crh-hero-chip .crh-total { font-size: 1.6rem; font-weight: 800; line-height: 1; }
.crh-hero-chip small { font-size: .68rem; text-transform: uppercase; letter-spacing: .08em; color: rgba(255,255,255,.75); }

/* ---- step sections ---- */
.crh-step { margin-bottom: 26px; }
.crh-step-head { display: flex; align-items: baseline; gap: 10px; margin-bottom: 12px; flex-wrap: wrap; }
.crh-step-num { display: inline-flex; align-items: center; justify-content: center; width: 26px; height: 26px;
  border-radius: 9px; font-size: .78rem; font-weight: 800; color: #fff; background: var(--accent, #6366f1);
  flex: none; transform: translateY(4px); box-shadow: 0 3px 8px -2px var(--accent, #6366f1); }
.crh-step-title { font-size: 1.02rem; font-weight: 700; color: var(--heading-color, #111827); letter-spacing: -.01em; }
.crh-step-sub { font-size: .76rem; color: var(--text-muted, #6b7280); }

/* ---- cards ---- */
.crh-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(255px, 1fr)); gap: 14px; }
.crh-card { position: relative; display: flex; flex-direction: column; gap: 8px; min-height: 122px;
  padding: 15px 16px 30px; border-radius: 14px; cursor: pointer; -webkit-user-select: none; user-select: none;
  background: var(--fg-color, #fff); border: 1px solid var(--border-color, #e5e7eb);
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease; }
.crh-card:hover { transform: translateY(-3px); border-color: var(--accent);
  box-shadow: 0 14px 28px -10px rgba(0,0,0,.18); }
.crh-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.crh-card-top { display: flex; align-items: center; gap: 10px; }
.crh-ico { display: flex; align-items: center; justify-content: center; width: 38px; height: 38px; flex: none;
  border-radius: 11px; font-size: 1.15rem; background: color-mix(in srgb, var(--accent) 13%, transparent); }
.crh-name { font-size: .9rem; font-weight: 650; line-height: 1.25; color: var(--heading-color, #111827); }
.crh-count { margin-left: auto; flex: none; min-width: 32px; text-align: center; padding: 3px 10px;
  border-radius: 999px; font-size: .76rem; font-weight: 800; color: var(--accent);
  background: color-mix(in srgb, var(--accent) 13%, transparent); }
.crh-tag { margin-left: auto; flex: none; padding: 3px 10px; border-radius: 999px; font-size: .66rem;
  font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--accent);
  border: 1px dashed color-mix(in srgb, var(--accent) 55%, transparent); }
.crh-desc { font-size: .77rem; line-height: 1.5; color: var(--text-muted, #6b7280); }
.crh-go { position: absolute; right: 14px; bottom: 10px; font-size: .72rem; font-weight: 650; color: var(--accent);
  opacity: 0; transform: translateX(-5px); transition: all .16s ease; }
.crh-card:hover .crh-go, .crh-card:focus-visible .crh-go { opacity: 1; transform: none; }

/* ---- how it works ---- */
.crh-how { margin-top: 30px; border-radius: 16px; overflow: hidden;
  background: var(--fg-color, #fff); border: 1px solid var(--border-color, #e5e7eb); }
.crh-how-head { padding: 16px 20px 12px; font-size: 1rem; font-weight: 700; letter-spacing: -.01em;
  color: var(--heading-color, #111827); border-bottom: 1px solid var(--border-color, #e5e7eb); }
.crh-how details { border-bottom: 1px solid var(--border-color, #e5e7eb); }
.crh-how details:last-child { border-bottom: none; }
.crh-how summary { display: flex; align-items: center; gap: 12px; padding: 13px 20px; cursor: pointer;
  font-size: .86rem; font-weight: 650; color: var(--heading-color, #111827); list-style: none; }
.crh-how summary::-webkit-details-marker { display: none; }
.crh-how summary:hover { background: color-mix(in srgb, var(--text-color, #000) 3%, transparent); }
.crh-how-ico { font-size: 1rem; width: 26px; text-align: center; flex: none; }
.crh-chev { margin-left: auto; font-size: 1.1rem; color: var(--text-muted, #9ca3af);
  transition: transform .16s ease; }
.crh-how details[open] .crh-chev { transform: rotate(90deg); }
.crh-how-body { padding: 0 20px 16px 58px; font-size: .8rem; line-height: 1.65;
  color: var(--text-muted, #4b5563); max-width: 900px; }

@media (max-width: 640px) {
  .crh-hero { padding: 22px 20px; }
  .crh-how-body { padding-left: 20px; }
}

script:
var _company = 'Motley Terpz';
const nikkiDash = (() => {

  const API_NIKKI  = "cannabis_management.api.Nikki";
  const API_JAMIE  = "cannabis_management.api.jamie.";
  const PAGE_SIZE  = 12;

  const $el = id => root_element.querySelector(`#${id}`);

  // ── State ──────────────────────────────────────────────────────────────────
  let currentPeriod      = 'monthly';
  let invPage            = 0;
  let invSearch          = "";
  let invTotal           = 0;
  let searchTimer        = null;
  let _arAllRows         = [];
  let _arPage            = 0;
  let samplesMonthOffset = 0;   // 0 = current month, -1 = last month, etc.
  const tablePages       = {};

  const now = frappe.datetime.get_today();

  // ────────────────────────────────────────────────────────────────────────────
  // Helpers
  // ────────────────────────────────────────────────────────────────────────────

  function getDateRange(period) {
    if (period === 'weekly')  return { from: frappe.datetime.add_days(now, -7), to: now, label: 'Last 7 Days' };
    if (period === 'monthly') return { from: now.substring(0, 7) + '-01', to: now, label: 'This Month' };
    return { from: null, to: null, label: 'All Time' };
  }

  function fmt(val) {
    const n = parseFloat(val || 0);
    if (isNaN(n)) return "–";
    return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
  }

  function fmtFloat(val) {
    return parseFloat(val || 0).toLocaleString(undefined, { maximumFractionDigits: 2 });
  }

  function fmtDate(val) {
    if (!val) return "–";
    try {
      const [y, m, d] = val.toString().split(" ")[0].split("-");
      return `${m}/${d}/${y}`;
    } catch(e) { return val; }
  }

  function monthLabel(offset) {
    const d = new Date();
    d.setDate(1);
    d.setMonth(d.getMonth() + offset);
    return d.toLocaleString('default', { month: 'long', year: 'numeric' });
  }

  function countUnique(arr, key) {
    return new Set(arr.map(r => r[key])).size;
  }

  function isOverdue(dueDateStr) {
    if (!dueDateStr) return false;
    return new Date(dueDateStr) < new Date();
  }

  function statusPill(status, dueDate) {
    let cls = "unpaid", label = status || "Unpaid";
    const s = (status || "").toLowerCase();
    if (s === "paid")                                       { cls = "paid";      label = "Paid"; }
    else if (s === "return")                                { cls = "return";    label = "Return"; }
    else if (s === "partly paid" || s === "partially paid") { cls = "partially"; label = "Partial"; }
    else if (isOverdue(dueDate))                            { cls = "overdue";   label = "Overdue"; }
    return `<span class="nd-status ${cls}">${label}</span>`;
  }

  function shimmerEl(id) {
    const el = $el(id);
    if (el) el.innerHTML = '<div class="nd-loading"><div class="nd-spinner"></div></div>';
  }

  function shimmerKpi(id) {
    const el = $el(id);
    if (el) { el.classList.remove('loaded', 'error'); el.innerHTML = '<span class="nd-shimmer"></span>'; }
  }

  function setKpiVal(id, html, subText) {
    const el = $el(id);
    if (el) { el.innerHTML = html; el.style.animation = "none"; el.offsetHeight; el.style.animation = "ndPop 0.3s ease both"; }
    if (subText !== undefined) { const sub = $el(id + '-sub'); if (sub) sub.textContent = subText; }
  }

  // ────────────────────────────────────────────────────────────────────────────
  // Period UI
  // ────────────────────────────────────────────────────────────────────────────

  function setPeriodUI(period) {
    root_element.querySelectorAll('.nd-period-btn').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.period === period);
    });
    const range = getDateRange(period);
    const periodLbl = $el('nd-period-label');       if (periodLbl) periodLbl.textContent = range.label;
    const salesLbl  = $el('nd-sales-period-label'); if (salesLbl)  salesLbl.textContent  = 'Sales — ' + range.label;
    const kpiLbl    = $el('nd-kpi-sales-label');    if (kpiLbl)    kpiLbl.textContent    = 'Sales — ' + range.label;
    const tsLbl     = $el('nd-ts-period-label');    if (tsLbl)     tsLbl.textContent     = 'Timesheets — ' + range.label;
    // Samples heading is managed by updateSamplesNav() since it has its own month offset
  }

  // ────────────────────────────────────────────────────────────────────────────
  // Generic paginated table renderer
  // ────────────────────────────────────────────────────────────────────────────

  function renderTable(containerId, columns, rows, emptyMsg) {
    const el = root_element.querySelector('#' + containerId);
    if (!el) return;

    if (!rows || !rows.length) {
      el.innerHTML = `<div class="nd-empty"><p>${emptyMsg || 'No data.'}</p></div>`;
      tablePages[containerId] = 0;
      return;
    }

    tablePages[containerId] = 0;

    function render(page) {
      const totalPages = Math.ceil(rows.length / PAGE_SIZE);
      page = Math.max(0, Math.min(page, totalPages - 1));
      tablePages[containerId] = page;

      const start    = page * PAGE_SIZE;
      const pageRows = rows.slice(start, start + PAGE_SIZE);

      let html = '<div style="overflow-x:auto"><table class="nd-table"><thead><tr>';
      columns.forEach(c => { html += `<th>${c.label}</th>`; });
      html += '</tr></thead><tbody>';
      pageRows.forEach(row => {
        html += '<tr>';
        columns.forEach(c => {
          const val = c.format ? c.format(row[c.key], row) : (row[c.key] != null ? row[c.key] : '—');
          html += `<td>${val}</td>`;
        });
        html += '</tr>';
      });
      html += '</tbody></table></div>';

      if (totalPages > 1) {
        const from = start + 1;
        const to   = Math.min(start + PAGE_SIZE, rows.length);
        html += `<div class="nd-pagination">
          <button class="nd-page-btn nd-page-prev" ${page === 0 ? 'disabled' : ''}>
            <svg viewBox="0 0 24 24"><path d="M15 18l-6-6 6-6"/></svg>
          </button>
          <span class="nd-page-info">${from}–${to} of ${rows.length}</span>
          <button class="nd-page-btn nd-page-next" ${page >= totalPages - 1 ? 'disabled' : ''}>
            <svg viewBox="0 0 24 24"><path d="M9 18l6-6-6-6"/></svg>
          </button>
        </div>`;
      }

      el.innerHTML = html;

      const prev = el.querySelector('.nd-page-prev');
      const next = el.querySelector('.nd-page-next');
      if (prev) prev.addEventListener('click', () => render(tablePages[containerId] - 1));
      if (next) next.addEventListener('click', () => render(tablePages[containerId] + 1));
    }

    render(0);
  }

  // ────────────────────────────────────────────────────────────────────────────
  // Init helpers
  // ────────────────────────────────────────────────────────────────────────────

  function initDateDisplay() {
    const el = $el("nd-date-display");
    if (el) el.textContent = new Date().toLocaleDateString("en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric" });
  }

  function initGLLink() {
    const today       = new Date();
    const toDate      = today.toISOString().split("T")[0];
    const fromDate    = new Date(today);
    fromDate.setFullYear(fromDate.getFullYear() - 1);
    const fromDateStr = fromDate.toISOString().split("T")[0];
    const accounts    = [
      "1101 - Petty Cash-Nikki - MT",
      "Blue Sky Bank - 0521 - MT - MT",
      "Blue Sky Bank - 7008 - MT",
      "1201 - Blue Sky Bank - 1115 - MT"
    ];
    const params = new URLSearchParams({
      company: _company, from_date: fromDateStr, to_date: toDate,
      account: JSON.stringify(accounts),
      categorize_by: "Categorize by Voucher (Consolidated)",
      include_dimensions: "1", include_default_book_entries: "1"
    });
    const el = root_element.querySelector("#gl-link");
    if (el) { el.href = `https://erp.motleyterpz.io/app/query-report/General%20Ledger?${params.toString()}`; el.target = "_blank"; }
  }

  // ────────────────────────────────────────────────────────────────────────────
  // Load: Sales
  // ────────────────────────────────────────────────────────────────────────────

  function loadSales(period) {
    const range = getDateRange(period);
    shimmerKpi('nd-kpi-sales');
    shimmerEl('nd-sales-table');

    frappe.call({
      method: API_JAMIE + 'get_sales_by_period',
      args: { period: period, company: _company },
      callback(r) {
        if (!r.message) return;
        const rows  = r.message.invoices || [];
        const total = r.message.total || 0;

        setKpiVal('nd-kpi-sales', fmt(total), `${rows.length} invoice${rows.length !== 1 ? 's' : ''} · ${range.label}`);

        const badge = $el('nd-sales-count');
        if (badge) badge.textContent = `${rows.length} invoices`;

        renderTable('nd-sales-table', [
          { label: 'Invoice',     key: 'name',              format: v => `<a class="nd-inv-link" href="/app/sales-invoice/${v}">${v}</a>` },
          { label: 'Customer',    key: 'customer_name' },
          { label: 'Date',        key: 'posting_date',      format: v => fmtDate(v) },
          { label: 'Due',         key: 'due_date',          format: v => v ? fmtDate(v) : '—' },
          { label: 'Total',       key: 'grand_total',       format: v => fmt(v) },
          { label: 'Outstanding', key: 'outstanding_amount', format: v => fmt(v) },
          { label: 'Status',      key: 'status',            format: (v, row) => statusPill(v, row.due_date) }
        ], rows, 'No invoices for this period.');
      },
      error() { setKpiVal('nd-kpi-sales', '<span style="font-size:13px;color:#94a3b8">Error</span>'); }
    });
  }

