  // ────────────────────────────────────────────────────────────────────────────
  // Load: Sample Giveaway  (month navigator — independent of period toggle)
  // ────────────────────────────────────────────────────────────────────────────

  function updateSamplesNav() {
    const navLbl = $el('nd-samples-month-label');
    if (navLbl) navLbl.textContent = monthLabel(samplesMonthOffset);

    const nextBtn = $el('nd-samples-next');
    if (nextBtn) nextBtn.disabled = samplesMonthOffset >= 0;

    const secLbl = $el('nd-samples-period-label');
    if (secLbl) secLbl.textContent = 'Sample Giveaway — ' + monthLabel(samplesMonthOffset);
  }

  function loadSamples(offset) {
    offset = (offset === undefined) ? samplesMonthOffset : offset;
    updateSamplesNav();

    shimmerKpi('nd-kpi-sample-lines');
    shimmerKpi('nd-kpi-sample-qty');
    shimmerKpi('nd-kpi-sample-recipients');
    shimmerEl('nd-samples-table');

    frappe.call({
      method: API_JAMIE + 'get_sample_giveaway',
      args: { period: 'monthly', month_offset: offset },
      callback(r) {
        if (!r.message) return;
        const data = r.message;
        const rows = data.rows || [];

        const linesEl = $el('nd-kpi-sample-lines');
        if (linesEl) { linesEl.innerHTML = rows.length; linesEl.style.animation = "none"; linesEl.offsetHeight; linesEl.style.animation = "ndPop 0.3s ease both"; }

        const linesSub    = $el('nd-kpi-sample-lines-sub');
        const invoiceCnt  = countUnique(rows, 'invoice_id');
        if (linesSub) linesSub.textContent = `across ${invoiceCnt} invoice${invoiceCnt !== 1 ? 's' : ''}`;

        const qtyEl = $el('nd-kpi-sample-qty');
        if (qtyEl) { qtyEl.innerHTML = parseFloat(data.total_qty || 0).toLocaleString(undefined, { maximumFractionDigits: 2 }); qtyEl.style.animation = "none"; qtyEl.offsetHeight; qtyEl.style.animation = "ndPop 0.3s ease both"; }

        const recEl = $el('nd-kpi-sample-recipients');
        if (recEl) { recEl.innerHTML = countUnique(rows, 'customer_id'); recEl.style.animation = "none"; recEl.offsetHeight; recEl.style.animation = "ndPop 0.3s ease both"; }

        const badge = $el('nd-samples-count');
        if (badge) badge.textContent = `${rows.length} line${rows.length !== 1 ? 's' : ''}`;

        renderTable('nd-samples-table', [
          { label: 'Given On',   key: 'given_on',   format: v => fmtDate(v) },
          { label: 'Given To',   key: 'given_to' },
          { label: 'Company',    key: 'company' },
          { label: 'Item Name',  key: 'item_name' },
          { label: 'Item Group', key: 'item_group' },
          { label: 'Qty',        key: 'qty',        format: v => `<span style="font-family:'DM Mono',monospace;font-size:12px;">${parseFloat(v || 0).toLocaleString(undefined, { maximumFractionDigits: 4 })}</span>` },
          { label: 'UOM',        key: 'uom' },
          { label: 'Invoice',    key: 'invoice_id', format: v => `<a class="nd-inv-link" href="/app/sales-invoice/${v}">${v}</a>` }
        ], rows, 'No sample giveaways for this period.');
      },
      error() {
        ['nd-kpi-sample-lines', 'nd-kpi-sample-qty', 'nd-kpi-sample-recipients'].forEach(id => {
          const el = $el(id);
          if (el) { el.textContent = '–'; el.classList.add('error'); }
        });
        const el = $el('nd-samples-table');
        if (el) el.innerHTML = '<p style="color:#94a3b8;font-size:13px;padding:12px 16px;">Error loading sample data.</p>';
      }
    });
  }

  function bindSamplesNav() {
    const prevBtn = $el('nd-samples-prev');
    const nextBtn = $el('nd-samples-next');
    if (prevBtn) prevBtn.addEventListener('click', () => { samplesMonthOffset -= 1; loadSamples(samplesMonthOffset); });
    if (nextBtn) nextBtn.addEventListener('click', () => { if (samplesMonthOffset >= 0) return; samplesMonthOffset += 1; loadSamples(samplesMonthOffset); });
  }

  // ────────────────────────────────────────────────────────────────────────────
  // Load: AR by Client
  // ────────────────────────────────────────────────────────────────────────────

  function renderARPage() {
    const rows    = _arAllRows;
    const start   = _arPage * PAGE_SIZE;
    const slice   = rows.slice(start, start + PAGE_SIZE);
    const hasMore = start + PAGE_SIZE < rows.length;
    const hasPrev = _arPage > 0;

    if (!slice.length) {
      $el("ar-client-table").innerHTML = `<div class="nd-empty"><svg viewBox="0 0 24 24"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg><p>No outstanding balances</p></div>`;
      return;
    }

    const trs = slice.map(r => {
      const collected    = parseFloat(r.total_billed || 0) - parseFloat(r.total_outstanding || 0);
      const paidPct      = r.total_billed > 0 ? Math.min((collected / r.total_billed) * 100, 100).toFixed(0) : 0;
      const overdueClass = parseFloat(r.total_outstanding) > 0 && isOverdue(r.oldest_due_date) ? "red" : "amber";
      return `<tr>
        <td class="bold">${r.client_name || r.client}</td>
        <td class="mono blue">${r.invoice_count}</td>
        <td class="right mono">${fmt(r.total_billed)}</td>
        <td class="right">
          <div class="nd-progress-cell" style="justify-content:flex-end">
            <div class="nd-progress-bg"><div class="nd-progress-fill" style="width:${paidPct}%"></div></div>
            <span class="green">${fmt(collected)}</span>
          </div>
        </td>
        <td class="right ${overdueClass}">${fmt(r.total_outstanding)}</td>
        <td class="mono" style="color:#94a3b8;font-size:11px">${fmtDate(r.oldest_due_date)}</td>
      </tr>`;
    }).join("");

    const from = start + 1, to = Math.min(start + PAGE_SIZE, rows.length);
    $el("ar-client-table").innerHTML = `
      <div style="overflow-x:auto">
        <table class="nd-table">
          <thead><tr>
            <th>Client</th><th>Invoices</th><th class="right">Total Billed</th>
            <th class="right">Collected</th><th class="right">Outstanding</th><th>Oldest Due</th>
          </tr></thead>
          <tbody>${trs}</tbody>
        </table>
      </div>
      <div class="nd-pagination">
        <button class="nd-page-btn" onclick="nikkiDash.arPrev()" ${!hasPrev ? "disabled" : ""}>
          <svg viewBox="0 0 24 24"><path d="M15 18l-6-6 6-6"/></svg>
        </button>
        <span class="nd-page-info">${from}–${to} of ${rows.length}</span>
        <button class="nd-page-btn" onclick="nikkiDash.arNext()" ${!hasMore ? "disabled" : ""}>
          <svg viewBox="0 0 24 24"><path d="M9 18l6-6-6-6"/></svg>
        </button>
      </div>`;
  }

  function loadARByClient() {
    $el("ar-client-table").innerHTML = `<div class="nd-loading"><div class="nd-spinner"></div></div>`;
    _arPage = 0;

    frappe.call({
      method: `${API_NIKKI}.get_ar_by_client`,
      callback(r) {
        _arAllRows = r.message || [];
        $el("ar-client-count").textContent = `${_arAllRows.length} client${_arAllRows.length !== 1 ? "s" : ""}`;
        if (!_arAllRows.length) {
          $el("ar-client-table").innerHTML = `<div class="nd-empty"><svg viewBox="0 0 24 24"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg><p>No outstanding balances</p></div>`;
          return;
        }
        renderARPage();
      },
      error() {
        $el("ar-client-table").innerHTML = `<div class="nd-empty"><p style="color:#e11d48">Failed to load AR data</p></div>`;
      }
    });
  }

  // ────────────────────────────────────────────────────────────────────────────
  // Load: All Invoices
  // ────────────────────────────────────────────────────────────────────────────

  function loadInvoices() {
    $el("inv-table").innerHTML = `<div class="nd-loading"><div class="nd-spinner"></div></div>`;
    $el("inv-pagination").innerHTML = "";

    const args = { limit: PAGE_SIZE, offset: invPage * PAGE_SIZE };
    if (invSearch && invSearch.trim()) args.search = invSearch.trim();

    frappe.call({
      method: `${API_NIKKI}.get_all_invoices`,
      args,
      callback(r) {
        if (!r || r.exc) {
          $el("inv-table").innerHTML = `<div class="nd-empty"><p style="color:#e11d48">Error: ${r && r.exc ? r.exc : 'Unknown error'}</p></div>`;
          $el("inv-count").textContent = "error";
          return;
        }
        const rows    = r.message || [];
        const hasMore = rows.length === PAGE_SIZE;
        invTotal = invPage * PAGE_SIZE + rows.length;

        $el("inv-count").textContent = `${invTotal}${hasMore ? "+" : ""} invoice${invTotal !== 1 ? "s" : ""}`;

        if (!rows.length && invPage === 0) {
          $el("inv-table").innerHTML = `<div class="nd-empty"><svg viewBox="0 0 24 24"><path d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg><p>No submitted invoices found</p></div>`;
          return;
        }

        const trs = rows.map(inv => {
          const link = `/app/sales-invoice/${encodeURIComponent(inv.invoice_id)}`;
          return `<tr>
            <td><a class="nd-inv-link" href="${link}" target="_blank">${inv.invoice_id}</a></td>
            <td class="bold">${inv.client || "–"}</td>
            <td class="mono" style="font-size:12px">${fmtDate(inv.posting_date)}</td>
            <td class="mono" style="font-size:12px;color:${isOverdue(inv.due_date) && parseFloat(inv.outstanding_amount) > 0 ? '#d97706':'#94a3b8'}">${fmtDate(inv.due_date)}</td>
            <td class="right mono">${fmt(inv.grand_total)}</td>
            <td class="right ${parseFloat(inv.outstanding_amount) > 0 ? 'amber' : 'green'}">${fmt(inv.outstanding_amount)}</td>
            <td>${statusPill(inv.status, inv.due_date)}</td>
          </tr>`;
        }).join("");

        $el("inv-table").innerHTML = `
          <div style="overflow-x:auto">
            <table class="nd-table">
              <thead><tr>
                <th>Invoice</th><th>Client</th><th>Date</th><th>Due</th>
                <th class="right">Total</th><th class="right">Outstanding</th><th>Status</th>
              </tr></thead>
              <tbody>${trs}</tbody>
            </table>
          </div>`;

        renderPagination(hasMore);
      },
      error(err) {
        console.error("Invoice load error:", err);
        $el("inv-table").innerHTML = `<div class="nd-empty"><p style="color:#e11d48">Failed to load invoices — check console</p></div>`;
        $el("inv-count").textContent = "error";
      }
    });
  }

  function renderPagination(hasMore) {
    const wrap = $el("inv-pagination");
    const from = invPage * PAGE_SIZE + 1;
    const to   = invPage * PAGE_SIZE + PAGE_SIZE;
    wrap.innerHTML = `
      <button class="nd-page-btn" onclick="nikkiDash.prevPage()" ${invPage === 0 ? "disabled" : ""}>
        <svg viewBox="0 0 24 24"><path d="M15 18l-6-6 6-6"/></svg>
      </button>
      <span class="nd-page-info">${from}–${to}</span>
      <button class="nd-page-btn" onclick="nikkiDash.nextPage()" ${!hasMore ? "disabled" : ""}>
        <svg viewBox="0 0 24 24"><path d="M9 18l6-6-6-6"/></svg>
      </button>`;
  }

  // ────────────────────────────────────────────────────────────────────────────
  // Master load
  // ────────────────────────────────────────────────────────────────────────────

  function loadAll(period) {
    currentPeriod = period;
    setPeriodUI(period);
    loadSales(period);
    loadAR(period);
    loadTimesheets(period);
    loadBatches();
    loadSamples(samplesMonthOffset);   // ← samples: always monthly, own offset
    loadARByClient();
    loadInvoices();
  }

  // ────────────────────────────────────────────────────────────────────────────
  // Public API
  // ────────────────────────────────────────────────────────────────────────────

  function reload() {
    const btn = $el("ndRefreshBtn");
    if (btn) btn.classList.add("spinning");
    invPage = 0;
    loadAll(currentPeriod);
    setTimeout(() => btn && btn.classList.remove("spinning"), 1200);
  }

  function searchInvoices(val) {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => { invSearch = val; invPage = 0; loadInvoices(); }, 350);
  }

  function nextPage() { invPage++; loadInvoices(); }
  function prevPage() { if (invPage > 0) { invPage--; loadInvoices(); } }
  function arNext()   { _arPage++; renderARPage(); }
  function arPrev()   { if (_arPage > 0) { _arPage--; renderARPage(); } }

  // ────────────────────────────────────────────────────────────────────────────
  // Init
  // ────────────────────────────────────────────────────────────────────────────

  function init() {
    initDateDisplay();
    initGLLink();
    bindSamplesNav();
    updateSamplesNav();

    root_element.querySelectorAll('.nd-period-btn').forEach(btn => {
      btn.addEventListener('click', function() {
        if (this.dataset.period !== currentPeriod) loadAll(this.dataset.period);
      });
    });

    loadAll('monthly');
  }


  const NKE_API = "cannabis_management.api.nikki_cash_dashboard.get_nikki_expense_summary";

  function loadExpenseWidget() {
    frappe.call({
      method: NKE_API,
      callback: function(r) {
        if (!r || !r.message) return;
        var d = r.message;
        setEl("nke-expenses",   fmtMoney(d.total_expenses));
        setEl("nke-reimbursed", fmtMoney(d.total_reimbursed));
        var netV = parseFloat(d.net_owed || 0);
        setEl("nke-net", '<span style="color:' + (netV > 0 ? "#7c3aed" : "#059669") + '">' + fmtMoney(netV) + "</span>");
        setEl("nke-cnt", (d.count || 0).toLocaleString());
        var badge = (typeof root_element !== "undefined" && root_element)
          ? root_element.querySelector("#nke-badge")
          : document.getElementById("nke-badge");
        if (badge) badge.textContent = (d.count || 0) + " entries";
        renderExpenseTable(d.recent || []);
      }
    });
  }

  function renderExpenseTable(rows) {
    var wrap = (typeof root_element !== "undefined" && root_element)
      ? root_element.querySelector("#nke-table")
      : document.getElementById("nke-table");
    if (!wrap) return;
    if (!rows.length) {
      wrap.innerHTML = '<div class="nck-empty">No expense entries yet — <a href="/nikki-expense-tracker">submit your first entry</a></div>';
      return;
    }
    var html = '<div style="overflow-x:auto"><table class="nck-tbl">' +
      '<thead><tr><th>Date</th><th>Direction</th><th class="nck-right">Amount</th><th>Type</th><th>Notes</th></tr></thead><tbody>';
    rows.forEach(function(r) {
      var isExp = r.direction === "Expense";
      var color = isExp ? "#c05621" : "#059669";
      var notes = r.notes ? r.notes.replace(/^\[.*?\]\s*/, "").substring(0, 55) + (r.notes.length > 55 ? "…" : "") : "–";
      html += "<tr>" +
        '<td class="nck-mono">' + fmtDate(r.date) + "</td>" +
        '<td><span class="nck-dir" style="color:' + color + '">' + (r.direction || "–") + "</span></td>" +
        '<td class="nck-mono nck-right" style="color:' + color + ';font-weight:600">' + fmtMoney(r.amount) + "</td>" +
        "<td>" + (r.transaction_type || "–") + "</td>" +
        '<td class="nck-notes">' + notes + "</td></tr>";
    });
    wrap.innerHTML = html + "</tbody></table></div>";
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    setTimeout(init, 100);
  }

  return { reload, searchInvoices, nextPage, prevPage, arNext, arPrev };
})();

style:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Mono:wght@400;500&display=swap');

.nikki-dash {
  --border: #e2e8f0;
  --border-hover: #cbd5e1;
  --text-primary: #1e293b;
  --text-secondary: #64748b;
  --text-muted: #94a3b8;
  --radius: 12px;
  --radius-sm: 8px;
  --bg: #ffffff;

  font-family: 'DM Sans', sans-serif;
  max-width: 1280px;
  margin: 0 auto;
  padding: 32px 24px 56px;
  background: #ffffff;
  min-height: 100vh;
}

/* ── Header ── */
.nd-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 16px;
}
.nd-eyebrow {
  font-size: 11px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase;
  color: #b45309; margin-bottom: 6px; display: flex; align-items: center; gap: 8px;
}
.nd-eyebrow::before {
  content: ''; display: inline-block; width: 16px; height: 2px;
  background: #b45309; border-radius: 1px;
}
.nd-title { font-size: 28px; font-weight: 700; color: var(--text-primary); margin: 0 0 4px; letter-spacing: -0.5px; }
.nd-subtitle { font-size: 13px; color: var(--text-secondary); margin: 0; }
.nd-subtitle span { color: #b45309; font-weight: 500; }

.nd-refresh-btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 8px 16px; border: 1.5px solid var(--border);
  border-radius: var(--radius-sm); background: #fff;
  color: var(--text-secondary); font-size: 12px; font-weight: 600;
  font-family: 'DM Sans', sans-serif; cursor: pointer; transition: all 0.15s;
}
.nd-refresh-btn:hover { border-color: #b45309; color: #b45309; }
.nd-refresh-btn svg { width: 14px; height: 14px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.nd-refresh-btn.spinning svg { animation: ndSpin 0.8s linear infinite; }

/* ═══════════════════════════════════════
   PERIOD TOGGLE BAR
   ═══════════════════════════════════════ */
.nd-period-bar {
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 10px; margin-bottom: 28px; padding: 10px 16px;
  background: #f8fafc; border: 1px solid var(--border); border-radius: var(--radius);
}
.nd-period-toggle {
  display: flex; gap: 4px; background: #fff;
  border: 1px solid var(--border); border-radius: 8px; padding: 3px;
}
.nd-period-btn {
  padding: 6px 20px; border: none; border-radius: 6px;
  background: transparent; font-size: 12px; font-weight: 600;
  font-family: 'DM Sans', sans-serif; color: var(--text-secondary);
  cursor: pointer; transition: all 0.18s; white-space: nowrap;
}
.nd-period-btn:hover:not(.active) { background: #f1f5f9; color: var(--text-primary); }
.nd-period-btn.active { background: #1e293b; color: #fff; box-shadow: 0 1px 4px rgba(0,0,0,0.15); }
.nd-period-label {
  font-size: 12px; font-weight: 600; color: var(--text-secondary);
  font-family: 'DM Mono', monospace; letter-spacing: 0.03em;
}

/* ── Section label ── */
.nd-section-label {
  font-size: 11px; font-weight: 600; letter-spacing: 1.5px;
  text-transform: uppercase; color: var(--text-muted);
  margin-bottom: 14px; display: flex; align-items: center; gap: 7px;
}
.nd-section-label svg { width: 14px; height: 14px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; opacity: 0.6; }

/* ── KPI grid ── */
.nd-kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  margin-bottom: 36px;
}
.nd-kpi {
  position: relative; background: #fff; border: 1px solid var(--border);
  border-radius: var(--radius); padding: 22px 20px 18px; overflow: hidden; transition: all 0.2s;
}
.nd-kpi:hover { border-color: var(--border-hover); transform: translateY(-2px); box-shadow: 0 4px 16px rgba(0,0,0,0.05); }
.nd-kpi-accent { position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--kc); opacity: 0.85; }
.nd-kpi-label { font-size: 11px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 10px; }
.nd-kpi-value { font-size: 28px; font-weight: 700; color: var(--kc); line-height: 1; margin-bottom: 6px; min-height: 34px; display: flex; align-items: flex-end; }
.nd-kpi-sub { font-size: 11px; color: var(--text-muted); font-family: 'DM Mono', monospace; }

.nd-shimmer {
  display: inline-block; width: 80px; height: 28px; border-radius: 6px;
  background: linear-gradient(110deg, #f1f5f9 25%, #e2e8f0 50%, #f1f5f9 75%);
  background-size: 200% 100%; animation: ndShimmer 1.4s ease-in-out infinite;
}

/* ── Quick links ── */
.nd-link-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 14px; margin-bottom: 36px;
}
.nd-link-card {
  display: flex; align-items: center; gap: 14px; background: #fff;
  border: 1px solid var(--border); border-radius: var(--radius);
  padding: 18px 18px 18px 20px; text-decoration: none; transition: all 0.2s;
  position: relative; overflow: hidden;
}
.nd-link-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0;
  height: 3px; background: var(--lc); opacity: 0; transition: opacity 0.2s;
}
.nd-link-card:hover { border-color: var(--border-hover); transform: translateY(-2px); box-shadow: 0 4px 16px rgba(0,0,0,0.05); }
.nd-link-card:hover::before { opacity: 1; }
.nd-link-card:hover .nd-link-arrow { opacity: 1; transform: translateX(0); }
.nd-link-icon {
  width: 42px; height: 42px; border-radius: var(--radius-sm);
  background: var(--lc-dim); display: flex; align-items: center;
  justify-content: center; flex-shrink: 0; transition: transform 0.2s;
}
.nd-link-card:hover .nd-link-icon { transform: scale(1.06); }
.nd-link-icon svg { width: 20px; height: 20px; stroke: var(--lc); fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.nd-link-body { flex: 1; min-width: 0; }
.nd-link-title { font-size: 14px; font-weight: 600; color: var(--text-primary); margin-bottom: 2px; }
.nd-link-desc  { font-size: 12px; color: var(--text-secondary); line-height: 1.4; }
.nd-link-arrow { flex-shrink: 0; opacity: 0; transform: translateX(-4px); transition: all 0.2s; }
.nd-link-arrow svg { width: 16px; height: 16px; stroke: var(--text-muted); fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

/* ── Card ── */
.nd-card { background: #fff; border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; margin-bottom: 8px; }
.nd-card-toolbar {
  display: flex; align-items: center; gap: 12px;
  padding: 14px 20px; border-bottom: 1px solid #f1f5f9; flex-wrap: wrap;
}
.nd-card-title { font-size: 13px; font-weight: 700; color: var(--text-primary); flex: 1; }
.nd-badge { font-size: 11px; background: #f1f5f9; color: #64748b; border-radius: 20px; padding: 3px 10px; font-weight: 600; white-space: nowrap; }

/* ── Search ── */
.nd-search-wrap { position: relative; display: flex; align-items: center; }
.nd-search-icon { position: absolute; left: 9px; width: 14px; height: 14px; stroke: var(--text-muted); fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; pointer-events: none; }
.nd-search-input {
  padding: 6px 10px 6px 28px; border: 1px solid var(--border); border-radius: 6px;
  font-size: 12px; font-family: 'DM Sans', sans-serif; width: 220px;
  background: #f8fafc; color: var(--text-primary); outline: none; transition: border-color 0.15s, background 0.15s;
}
.nd-search-input:focus { border-color: #2563eb; background: #fff; }

/* ── Tables ── */
.nd-table { width: 100%; border-collapse: collapse; }
.nd-table thead th {
  font-size: 10.5px; font-weight: 700; color: var(--text-muted); text-transform: uppercase;
  letter-spacing: 0.07em; padding: 10px 16px; text-align: left;
  background: #fafbfc; border-bottom: 1px solid #f1f5f9; white-space: nowrap;
}
.nd-table thead th.right { text-align: right; }
.nd-table tbody tr { border-bottom: 1px solid #f8fafc; transition: background 0.12s; }
.nd-table tbody tr:last-child { border-bottom: none; }
.nd-table tbody tr:hover { background: #fafbfc; }
.nd-table tbody td { padding: 11px 16px; font-size: 13px; color: var(--text-secondary); white-space: nowrap; }
.nd-table td.right { text-align: right; }
.nd-table td.bold  { font-weight: 600; color: var(--text-primary); }
.nd-table td.mono  { font-family: 'DM Mono', monospace; font-size: 12px; }
.nd-table td.green { color: #059669; font-weight: 600; font-family: 'DM Mono', monospace; }
.nd-table td.amber { color: #d97706; font-weight: 600; font-family: 'DM Mono', monospace; }
.nd-table td.red   { color: #e11d48; font-weight: 600; font-family: 'DM Mono', monospace; }
.nd-table td.blue  { color: #2563eb; font-family: 'DM Mono', monospace; }

/* Progress bar */
.nd-progress-cell { display: flex; align-items: center; gap: 8px; }
.nd-progress-bg { flex: 1; max-width: 80px; height: 5px; background: #f1f5f9; border-radius: 3px; overflow: hidden; }
.nd-progress-fill { height: 100%; border-radius: 3px; background: linear-gradient(90deg, #059669, #34d399); transition: width 0.5s ease; }

/* Status pill */
.nd-status { display: inline-block; padding: 2px 8px; border-radius: 20px; font-size: 11px; font-weight: 600; }
.nd-status.paid      { background: #d1fae5; color: #065f46; }
.nd-status.unpaid    { background: #fee2e2; color: #991b1b; }
.nd-status.overdue   { background: #fef3c7; color: #92400e; }
.nd-status.partially { background: #dbeafe; color: #1e40af; }
.nd-status.return    { background: #f3e8ff; color: #6b21a8; }

/* Invoice link */
.nd-inv-link { color: #2563eb; text-decoration: none; font-family: 'DM Mono', monospace; font-size: 12px; font-weight: 500; }
.nd-inv-link:hover { text-decoration: underline; }

/* ── Pagination ── */
.nd-pagination {
  display: flex; align-items: center; justify-content: flex-end;
  gap: 8px; padding: 10px 16px; border-top: 1px solid #f1f5f9;
}

/* ══════════════════════════════════════════════════
   SAMPLE GIVEAWAY additions — Nikki Dashboard
   Append to nikki_dashboard.css
   ══════════════════════════════════════════════════ */

/* Section heading + month navigator on the same row */
.nikki-dash .nd-samples-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 0;
}

/* Month navigator pill */
.nikki-dash .nd-month-nav {
  display: inline-flex;
  align-items: center;
  background: #fff;
  border: 1.5px solid #e2e8f0;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
}

.nikki-dash .nd-month-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: none;
  background: transparent;
  cursor: pointer;
  color: #64748b;
  transition: background 0.15s, color 0.15s;
  flex-shrink: 0;
}
.nikki-dash .nd-month-btn:hover:not([disabled]) {
  background: #f1f5f9;
  color: #9333ea;
}
.nikki-dash .nd-month-btn[disabled] {
  opacity: 0.3;
  cursor: not-allowed;
}
.nikki-dash .nd-month-btn svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.nikki-dash .nd-month-label {
  padding: 0 18px;
  font-size: 13px;
  font-weight: 700;
  color: #1e293b;
  font-family: 'DM Sans', sans-serif;
  white-space: nowrap;
  min-width: 130px;
  text-align: center;
  border-left: 1px solid #e2e8f0;
  border-right: 1px solid #e2e8f0;
  line-height: 36px;
}

/* KPI grid — 3 columns for samples row */
.nikki-dash .nd-samples-kpi-grid {
  grid-template-columns: repeat(3, 1fr);
}

/* Purple left-accent on the samples card */
.nikki-dash .nd-card.nd-samples-card {
  border-left: 3px solid rgba(147, 51, 234, 0.35);
}

/* Responsive */
@media (max-width: 1024px) {
  .nikki-dash .nd-samples-kpi-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (max-width: 640px) {
  .nikki-dash .nd-samples-kpi-grid {
    grid-template-columns: 1fr;
  }
  .nikki-dash .nd-samples-header {
    flex-direction: column;
    align-items: flex-start;
  }
  .nikki-dash .nd-month-label {
    min-width: 100px;
    padding: 0 10px;
  }
}

.nd-page-btn {
  display: flex; align-items: center; justify-content: center;
  width: 30px; height: 30px; border: 1.5px solid var(--border);
  border-radius: 6px; background: #fff; cursor: pointer; transition: all 0.15s; padding: 0;
}
.nd-page-btn:hover:not([disabled]) { border-color: #b45309; color: #b45309; }
.nd-page-btn[disabled] { opacity: 0.35; cursor: not-allowed; }
.nd-page-btn svg { width: 14px; height: 14px; stroke: currentColor; fill: none; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
.nd-page-info { font-size: 11px; font-weight: 600; color: var(--text-muted); font-family: 'DM Mono', monospace; min-width: 80px; text-align: center; }

/* Loading / empty */
.nd-loading { text-align: center; padding: 50px; }
.nd-spinner {
  display: inline-block; width: 24px; height: 24px;
  border: 2px solid #e2e8f0; border-top-color: #b45309;
  border-radius: 50%; animation: ndSpin 0.7s linear infinite;
}
.nd-empty { text-align: center; padding: 60px 20px; }
.nd-empty svg { width: 40px; height: 40px; stroke: #cbd5e1; fill: none; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; margin-bottom: 10px; }
.nd-empty p { font-size: 13px; color: var(--text-muted); margin: 0; }

/* ── Animations ── */
@keyframes ndShimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
@keyframes ndSpin { to { transform: rotate(360deg); } }
@keyframes ndPop {
  0%   { opacity: 0; transform: scale(0.85) translateY(6px); }
  100% { opacity: 1; transform: scale(1) translateY(0); }
}

/* ── Responsive ── */
@media (max-width: 1024px) { .nd-kpi-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 768px) {
  .nd-period-bar { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 640px) {
  .nikki-dash { padding: 16px 12px 40px; }
  .nd-title { font-size: 22px; }
  .nd-kpi-grid { grid-template-columns: 1fr; }
  .nd-link-grid { grid-template-columns: 1fr; }
  .nd-search-input { width: 150px; }
  .nd-period-toggle { width: 100%; }
  .nd-period-btn { flex: 1; text-align: center; }
}
/* ── Nikki Cash Ledger Widget ─────────────────────────────────────────── */
.nck-wrap { margin-top: 36px; border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden; background: #fff; }
.nck-bar { display: flex; justify-content: space-between; align-items: center; padding: 16px 20px; background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%); flex-wrap: wrap; gap: 10px; }
.nck-bar-left { display: flex; align-items: center; gap: 10px; }
.nck-icon { width: 18px; height: 18px; stroke: #10b981; fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.nck-heading { font-size: 14px; font-weight: 700; color: #f8fafc; letter-spacing: -0.2px; }
.nck-live-dot { width: 7px; height: 7px; border-radius: 50%; background: #10b981; box-shadow: 0 0 0 0 rgba(16,185,129,0.4); animation: nckPulse 1.8s ease-in-out infinite; }
@keyframes nckPulse { 0%,100% { box-shadow: 0 0 0 0 rgba(16,185,129,0.4); } 50% { box-shadow: 0 0 0 5px rgba(16,185,129,0); } }
.nck-bar-right { display: flex; gap: 8px; }
.nck-btn-new { padding: 6px 14px; border-radius: 6px; font-size: 12px; font-weight: 600; background: #10b981; color: #fff; text-decoration: none; transition: background 0.15s; }
.nck-btn-new:hover { background: #059669; color: #fff; }
.nck-btn-all { padding: 6px 14px; border-radius: 6px; font-size: 12px; font-weight: 600; background: rgba(255,255,255,0.1); color: #94a3b8; border: 1px solid rgba(255,255,255,0.15); text-decoration: none; transition: all 0.15s; }
.nck-btn-all:hover { background: rgba(255,255,255,0.18); color: #f1f5f9; }
.nck-kpi-row { display: grid; grid-template-columns: repeat(4,1fr); border-bottom: 1px solid #f1f5f9; }
.nck-kpi { padding: 18px 20px; border-right: 1px solid #f1f5f9; position: relative; }
.nck-kpi:last-child { border-right: none; }
.nck-kpi-dot { position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--nkc); }
.nck-kpi-label { font-size: 10px; font-weight: 600; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 6px; }
.nck-kpi-value { font-size: 22px; font-weight: 700; color: var(--nkc); font-family: 'DM Mono', monospace; }
.nck-table-card { padding: 0; }
.nck-table-header { display: flex; align-items: center; justify-content: space-between; padding: 12px 20px; border-bottom: 1px solid #f1f5f9; }
.nck-table-title { font-size: 12px; font-weight: 600; color: #475569; text-transform: uppercase; letter-spacing: 0.06em; }
.nck-badge { font-size: 11px; font-weight: 600; color: #64748b; background: #f1f5f9; border-radius: 20px; padding: 2px 10px; }
.nck-loading { display: flex; justify-content: center; align-items: center; padding: 40px; }
.nck-spinner { width: 24px; height: 24px; border-radius: 50%; border: 2px solid #e2e8f0; border-top-color: #10b981; animation: nckSpin 0.7s linear infinite; }
@keyframes nckSpin { to { transform: rotate(360deg); } }
.nck-empty { padding: 24px 20px; text-align: center; color: #94a3b8; font-size: 13px; }
.nck-empty a { color: #10b981; }
.nck-tbl { width: 100%; border-collapse: collapse; font-size: 13px; }
.nck-tbl thead tr { border-bottom: 1px solid #f1f5f9; }
.nck-tbl thead th { padding: 10px 16px; text-align: left; font-size: 11px; font-weight: 600; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.05em; }
.nck-tbl thead th.nck-right { text-align: right; }
.nck-tbl tbody tr { border-bottom: 1px solid #f8fafc; transition: background 0.1s; }
.nck-tbl tbody tr:last-child { border-bottom: none; }
.nck-tbl tbody tr:hover { background: #f8fafc; }
.nck-tbl td { padding: 10px 16px; color: #334155; vertical-align: middle; }
.nck-mono { font-family: 'DM Mono', monospace; font-size: 12px; }
.nck-right { text-align: right; }
.nck-dir { font-weight: 600; }
.nck-pill { display: inline-block; padding: 2px 9px; border-radius: 12px; font-size: 11px; font-weight: 600; background: #f1f5f9; color: #64748b; }
.nck-open     { background: #fef3c7; color: #b45309; }
.nck-reviewed { background: #dbeafe; color: #2563eb; }
.nck-done     { background: #dcfce7; color: #166534; }
@media (max-width: 640px) { .nck-kpi-row { grid-template-columns: repeat(2,1fr); } .nck-kpi:nth-child(2) { border-right: none; } }

.nck-notes { max-width:180px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:#718096; font-size:12px; }


/* nikki-scrollable-tables */
#nck-table, #nke-table { max-height: 420px; overflow: auto; }
#nck-table > div, #nke-table > div { overflow: visible; }
.nck-tbl thead th { position: sticky; top: 0; background: #fff; z-index: 3; box-shadow: 0 1px 0 #f1f5f9; }
/* thin scrollbar */
#nck-table::-webkit-scrollbar, #nke-table::-webkit-scrollbar { width: 8px; height: 8px; }
#nck-table::-webkit-scrollbar-thumb, #nke-table::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 4px; }
#nck-table::-webkit-scrollbar-track, #nke-table::-webkit-scrollbar-track { background: transparent; }
